from specflow.refmodel.temporal import TO_END, after, eventually, throughout, edges, worst


def decide(trace):
    def out(row, name):
        return row.get("outputs", {}).get(name)

    def inp(row, name):
        return row.get("inputs", {}).get(name)

    active_rises = edges(trace, "fsm_active", "rise")

    def opens(row):
        return (
            row.get("edge") in active_rises
            and out(row, "fsm_active") == 1
            and inp(row, "ena") == 1
        )

    def aborts(row):
        return (
            out(row, "al") == 1
            or inp(row, "nReset") == 0
            or inp(row, "rst") == 1
        )

    windows = after(
        trace,
        opens,
        until=lambda r: out(r, "cmd_ack") == 1,
        aborts=aborts,
    )

    scl_changes = edges(trace, "scl_oen", "change")
    sda_changes = edges(trace, "sda_oen", "change")
    verdicts = []

    for window in windows:
        verdicts.append(
            eventually(
                window,
                lambda r: r.get("edge") in scl_changes,
                strong=True,
                after_activation=True,
            )
        )

        rows = window.rows
        is_start = any(out(r, "in_start_sequence") == 1 for r in rows)
        is_stop = any(out(r, "in_stop_sequence") == 1 for r in rows)
        is_read = any(out(r, "in_read_sequence") == 1 for r in rows)
        is_write = any(out(r, "in_write_sequence") == 1 for r in rows)

        if is_start or is_stop:
            verdicts.append(
                eventually(
                    window,
                    lambda r: r.get("edge") in sda_changes,
                    strong=True,
                    after_activation=True,
                )
            )
        elif is_read:
            verdicts.append(
                throughout(
                    window,
                    lambda r: out(r, "sda_oen") == 1,
                    after_activation=True,
                )
            )
        elif is_write:
            expected = 0 if window.value("din") == 0 else 1
            verdicts.append(
                throughout(
                    window,
                    lambda r, expected=expected: out(r, "sda_oen") == expected,
                    after_activation=True,
                )
            )

    return worst(verdicts)

def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    def inp(row, name):
        return row.get('inputs', {}).get(name)

    def probe(row, name):
        return bool(out(row, name))

    def rising(name, i):
        return probe(trace[i], name) and (i == 0 or not probe(trace[i - 1], name))

    def span_from(i, name):
        indices = []
        for k in range(i, len(trace)):
            if not probe(trace[k], name):
                break
            indices.append(k)
        return indices

    failures = []
    undecided = []
    saw_activation = False

    sequences = [
        ('in_start_sequence', 'START'),
        ('in_stop_sequence', 'STOP'),
        ('in_write_sequence', 'WRITE'),
        ('in_read_sequence', 'READ'),
    ]

    for probe_name, label in sequences:
        for i, row in enumerate(trace):
            if not rising(probe_name, i):
                continue
            if inp(row, 'ena') != 1 or inp(row, 'nReset') == 0 or inp(row, 'rst') == 1:
                continue

            saw_activation = True
            indices = span_from(i, probe_name)
            if not indices:
                continue

            ack_positions = [k for k in indices if out(trace[k], 'cmd_ack') == 1]
            aborted = any(out(trace[k], 'al') == 1 for k in indices)
            if not aborted and not ack_positions:
                if indices[-1] == len(trace) - 1:
                    undecided.append((trace[i]['edge'], label + ' command was active but the trace ended before completion'))
                else:
                    failures.append((trace[i]['edge'], label + ' command completed without cmd_ack'))

            if label == 'START':
                low_sda = [k for k in indices if out(trace[k], 'sda_oen') == 0 and out(trace[k], 'scl_oen') == 1]
                low_scl = [k for k in indices if out(trace[k], 'scl_oen') == 0]
                if not low_sda or not low_scl or low_sda[0] >= low_scl[0]:
                    failures.append((trace[i]['edge'], 'START did not drive SDA low before pulling SCL low'))

            elif label == 'STOP':
                low_sda = [k for k in indices if out(trace[k], 'sda_oen') == 0]
                released_scl = [k for k in indices if out(trace[k], 'scl_oen') == 1]
                released_sda = [k for k in indices if out(trace[k], 'sda_oen') == 1]
                if not low_sda or not released_scl or not released_sda:
                    failures.append((trace[i]['edge'], 'STOP did not contain the required SDA-low, SCL-release, and SDA-release phases'))
                elif not (low_sda[0] < released_scl[0] < released_sda[0]):
                    failures.append((trace[i]['edge'], 'STOP phases occurred in the wrong order'))

            elif label == 'WRITE':
                desired_sda_oen = 1 if inp(row, 'din') == 1 else 0
                bit_phase = [k for k in indices if out(trace[k], 'scl_oen') == 1 and out(trace[k], 'sda_oen') == desired_sda_oen]
                scl_low_after = [k for k in indices if bit_phase and k > bit_phase[0] and out(trace[k], 'scl_oen') == 0]
                if not bit_phase or not scl_low_after:
                    failures.append((trace[i]['edge'], 'WRITE did not present the din-selected SDA bit during the released SCL phase'))

            elif label == 'READ':
                if not any(out(trace[k], 'sda_oen') == 1 and out(trace[k], 'scl_oen') == 1 for k in indices):
                    failures.append((trace[i]['edge'], 'READ did not release SDA during the released SCL phase'))

    for i, row in enumerate(trace):
        if inp(row, 'ena') != 1 or inp(row, 'nReset') == 0 or inp(row, 'rst') == 1:
            continue

        if probe(row, 'start_condition') and (i == 0 or not probe(trace[i - 1], 'start_condition')):
            saw_activation = True
            if not any(out(trace[k], 'busy') == 1 for k in range(i, len(trace))):
                failures.append((row['edge'], 'filtered START occurred without busy becoming asserted'))

        if probe(row, 'stop_condition') and (i == 0 or not probe(trace[i - 1], 'stop_condition')):
            saw_activation = True
            if not any(out(trace[k], 'busy') == 0 for k in range(i, len(trace))):
                failures.append((row['edge'], 'filtered STOP occurred without busy clearing'))

        if probe(row, 'sda_arbitration_check') and inp(row, 'sda_i') == 0:
            saw_activation = True
            if not any(out(trace[k], 'al') == 1 for k in range(i, len(trace))):
                failures.append((row['edge'], 'arbitration-check condition with SDA low did not assert al'))

    if failures:
        edge, detail = failures[0]
        return (False, edge, detail)
    if not saw_activation:
        return (None, None, 'no enabled command sequence or relevant filtered bus condition occurred')
    if undecided:
        edge, detail = undecided[0]
        return (None, edge, detail)
    return (True, None, 'all exercised enabled command and filtered-bus capabilities satisfied their declared output obligations')

def decide(trace):
    if not trace:
        return (None, None, 'no interface observation occurred')

    for row in trace:
        outputs = row.get('outputs', {})
        bad = []

        if outputs.get('scl_o') != 0:
            bad.append('scl_o is not constant low')
        if outputs.get('sda_o') != 0:
            bad.append('sda_o is not constant low')

        for port in ('scl_oen', 'sda_oen'):
            value = outputs.get(port)
            if value not in (0, 1):
                bad.append(f'{port} is not a valid active-low enable value')

        if bad:
            return (False, row.get('edge'), '; '.join(bad))

    return (True, None, 'scl_o and sda_o remain low; output enables remain valid active-low controls')

def decide(trace):
    if not trace:
        return (None, None, 'module operation was not observed in this trace')

    for row in trace:
        outputs = row['outputs']
        if outputs['scl_o'] != 0:
            return (False, row['edge'], 'scl_o is not the required constant low drive value')
        if outputs['sda_o'] != 0:
            return (False, row['edge'], 'sda_o is not the required constant low drive value')

    return (True, None, 'scl_o and sda_o remained constant low throughout module operation')

def decide(trace):
    from specflow.refmodel.temporal import after, edges, eventually, throughout, worst

    def output(row, name):
        return row.get('outputs', {}).get(name)

    active_rises = edges(trace, 'fsm_active', 'rise')
    enable_changes = (
        edges(trace, 'scl_oen', 'change')
        | edges(trace, 'sda_oen', 'change')
    )

    def command_sequence(row):
        return (
            row.get('edge') in active_rises
            and output(row, 'fsm_active') == 1
            and row.get('inputs', {}).get('cmd') in (1, 2, 4, 8)
        )

    def sequence_ended(row):
        return output(row, 'fsm_active') == 0

    windows = after(
        trace,
        command_sequence,
        until=sequence_ended,
    )

    if not windows:
        return (None, None, 'no commanded command-controlled sequence was observed')

    verdicts = []
    for window in windows:
        verdicts.append(
            throughout(
                window,
                lambda row: output(row, 'scl_o') == 0 and output(row, 'sda_o') == 0,
                after_activation=False,
            )
        )
        verdicts.append(
            eventually(
                window,
                lambda row: row.get('edge') in enable_changes,
                strong=True,
                after_activation=False,
            )
        )

    return worst(verdicts)

from specflow.refmodel.temporal import after

def decide(trace):
    def out(row, port):
        return row.get('outputs', {}).get(port)

    def any_condition(conditions):
        def predicate(row):
            values = row.get('outputs', {})
            values = {**row.get('inputs', {}), **values}
            return any(
                all(values.get(port) == value for port, value in condition.items())
                for condition in conditions
            )
        return predicate

    aborts = any_condition([
        {'al': 1},
        {'nReset': 0},
        {'rst': 1},
    ])

    def phase_seen(rows, start, phase):
        for i in range(start, len(rows)):
            row = rows[i]
            if all(out(row, port) == value for port, value in phase.items()):
                return i
        return None

    def sequence_verdict(window, phases):
        rows = window.rows
        if not rows:
            return (None, None, 'the command window contained no post-activation state')
        if not window.closed:
            return (None, None, 'the command did not reach cmd_ack before the trace ended')

        pos = 0
        for phase in phases:
            found = phase_seen(rows, pos, phase)
            if found is None:
                return (
                    False,
                    rows[-1]['edge'],
                    'missing required bit-level output-enable phase '
                    + str(phase)
                    + ' before cmd_ack'
                )
            pos = found + 1

        return (
            True,
            rows[pos - 1]['edge'],
            'required bit-level output-enable phases occurred in order before cmd_ack'
        )

    verdicts = []
    probes = [
        ('in_start_sequence', lambda w: [
            {'scl_oen': 1, 'sda_oen': 0},
            {'scl_oen': 0, 'sda_oen': 0},
        ]),
        ('in_stop_sequence', lambda w: [
            {'scl_oen': 1, 'sda_oen': 0},
            {'scl_oen': 1, 'sda_oen': 1},
        ]),
        ('in_read_sequence', lambda w: [
            {'scl_oen': 1, 'sda_oen': 1},
            {'scl_oen': 0},
        ]),
        ('in_write_sequence', lambda w: [
            {'scl_oen': 1, 'sda_oen': w.value('din')},
            {'scl_oen': 0},
        ]),
    ]

    for probe, phases_for in probes:
        windows = after(
            trace,
            lambda row, probe=probe: out(row, probe) == 1 and row.get('inputs', {}).get('ena') == 1,
            until=lambda row: out(row, 'cmd_ack') == 1,
            aborts=aborts,
        )
        for window in windows:
            verdicts.append(sequence_verdict(window, phases_for(window)))

    if not verdicts:
        return (None, None, 'no supported bit-level command sequence occurred')

    for verdict in verdicts:
        if verdict[0] is False:
            return verdict
    for verdict in verdicts:
        if verdict[0] is True:
            return verdict
    return (None, None, 'command sequence activation occurred but no complete transaction was observed')

def decide(trace):
    windows = []
    active = False
    start = None

    for i, row in enumerate(trace):
        rst = row.get('inputs', {}).get('rst')
        if rst == 1 and not active:
            active = True
            start = i
        elif rst != 1 and active:
            active = False
            start = None

        if active and start is not None:
            windows.append((start, row))

    if not windows:
        return (None, None, 'rst was never asserted')

    for start, row in windows:
        scl_oen = row.get('outputs', {}).get('scl_oen')
        if scl_oen != 1:
            return (False, row.get('edge'), 'synchronous active-high rst is asserted, but scl_oen is not released (expected scl_oen == 1)')

    return (True, None, 'while rst is asserted, synchronous reset leaves declared output scl_oen released')

def decide(trace):
    def reset_outputs(row):
        outputs = row.get('outputs', {})
        return (
            outputs.get('cmd_ack') == 0
            and outputs.get('busy') == 0
            and outputs.get('al') == 0
            and outputs.get('scl_oen') == 1
            and outputs.get('sda_oen') == 1
        )

    reset_rows = [
        row for row in trace
        if row.get('inputs', {}).get('rst') == 1
    ]

    if not reset_rows:
        return (None, None, 'rst was never asserted; synchronous reset was not exercised')

    for row in reset_rows:
        if not reset_outputs(row):
            return (
                False,
                row.get('edge'),
                'while rst is asserted, synchronous reset requires '
                'cmd_ack, busy, and al low and scl_oen and sda_oen high'
            )

    return (
        True,
        reset_rows[0].get('edge'),
        'reset outputs held at their specified synchronous-reset levels while rst was asserted'
    )

def decide(trace):
    reset_rows = []
    for row in trace:
        if row.get('inputs', {}).get('nReset') == 0:
            reset_rows.append(row)

    if not reset_rows:
        return (None, None, 'nReset was never low; asynchronous reset was not exercised')

    for row in reset_rows:
        if row.get('outputs', {}).get('scl_oen') != 1:
            return (False, row.get('edge'), 'while nReset is low, scl_oen is not initialized to 1 immediately and independently of clk')

    return (True, reset_rows[0].get('edge'), 'throughout the observed nReset-low window, scl_oen is initialized to 1 immediately and independently of clk')

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, throughout, worst

    def active_disabled(row):
        return (
            row['inputs'].get('ena') == 0
            and row['outputs'].get('fsm_active') == 1
        )

    def released_or_inactive(row):
        return (
            row['inputs'].get('ena') == 1
            or row['outputs'].get('fsm_active') == 0
        )

    windows = after(
        trace,
        active_disabled,
        until=released_or_inactive,
    )
    return worst([
        throughout(
            w,
            lambda r: r['outputs'].get('cmd_ack') == 0,
            after_activation=False,
        )
        for w in windows
    ])

from specflow.refmodel.temporal import WHILE_ACTIVE, after, throughout, worst


def decide(trace):
    def out(row, name, default=0):
        return row.get("outputs", {}).get(name, default)

    def supported_active(row):
        return any(out(row, probe) == 1 for probe in (
            "in_start_sequence",
            "in_stop_sequence",
            "in_read_sequence",
            "in_write_sequence",
        ))

    # Coverage evidence only: this trace must show the ordinary enabled
    # command-completion behavior, otherwise the route's two cases were not
    # both exercised.
    enabled_active_seen = False
    enabled_completion_seen = False
    for row in trace:
        if out(row, "nReset", 1) == 0 or row.get("inputs", {}).get("rst", 0) == 1:
            enabled_active_seen = False
            continue
        if row.get("inputs", {}).get("ena") == 1 and supported_active(row):
            enabled_active_seen = True
        if (row.get("inputs", {}).get("ena") == 1
                and out(row, "cmd_ack") == 1
                and enabled_active_seen):
            enabled_completion_seen = True

    if not enabled_completion_seen:
        return (None, None,
                "no enabled supported-command completion was observed; the cmd_ack route was not exercised in both cases")

    applies = lambda row: (
        row.get("inputs", {}).get("ena") == 0
        and out(row, "nReset", 1) == 1
        and row.get("inputs", {}).get("rst", 0) == 0
        and out(row, "al") == 0
        and supported_active(row)
    )

    windows = after(trace, applies, until=WHILE_ACTIVE)
    if not windows:
        return (None, None,
                "ena was not observed low during an active supported command")

    return worst([
        throughout(
            window,
            lambda row: out(row, "cmd_ack") == 0,
            after_activation=False,
        )
        for window in windows
    ])

def decide(trace):
    from specflow.refmodel.temporal import WHILE_ACTIVE, after, throughout, worst

    def out(row, name):
        return row.get("outputs", {}).get(name)

    def active_sequence(row):
        return any(
            out(row, probe) == 1
            for probe in (
                "in_start_sequence",
                "in_stop_sequence",
                "in_read_sequence",
                "in_write_sequence",
            )
        )

    def filtered_start_or_stop(row):
        return (
            out(row, "start_condition") == 1
            or out(row, "stop_condition") == 1
        )

    scl_windows = after(
        trace,
        lambda r: r.get("inputs", {}).get("ena") == 0 and active_sequence(r),
        until=WHILE_ACTIVE,
    )
    busy_windows = after(
        trace,
        lambda r: (
            r.get("inputs", {}).get("ena") == 0
            and filtered_start_or_stop(r)
        ),
        until=WHILE_ACTIVE,
    )

    verdicts = []

    for window in scl_windows:
        verdicts.append(
            throughout(
                window,
                lambda r, w=window: out(r, "scl_oen") == w.value("scl_oen"),
                after_activation=False,
            )
        )

    for window in busy_windows:
        verdicts.append(
            throughout(
                window,
                lambda r, w=window: out(r, "busy") == w.value("busy"),
                after_activation=False,
            )
        )

    return worst(verdicts)

from specflow.refmodel.temporal import WHILE_ACTIVE, after, eventually, worst


def _holds(cond):
    def predicate(row):
        for port, value in cond.items():
            actual = row['outputs'].get(port, row['inputs'].get(port))
            if actual != value:
                return False
        return True
    return predicate


def _any(alternatives):
    predicates = [_holds(condition) for condition in alternatives]
    return lambda row: any(predicate(row) for predicate in predicates)


def decide(trace):
    activation = _holds({'ena': 1})
    aborts = _any([
        {'nReset': 0},
        {'rst': 1},
    ])
    windows = after(
        trace,
        activation,
        until=WHILE_ACTIVE,
        aborts=aborts,
    )
    return worst([
        eventually(
            window,
            lambda row: row['outputs'].get('clk_en_asserted') == 1,
            strong=False,
            after_activation=False,
        )
        for window in windows
    ])

def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    events = []
    previous = False
    for i, row in enumerate(trace):
        current = bool(out(row, 'filter_sample_tick'))
        if current and not previous:
            events.append(i)
        previous = current

    observations = []
    for left, right in zip(events, events[1:]):
        first = trace[left]
        last = trace[right]
        clk_cnt = first.get('inputs', {}).get('clk_cnt')
        if clk_cnt is None or last.get('inputs', {}).get('clk_cnt') != clk_cnt:
            continue

        valid = True
        enabled_edges = 0
        for row in trace[left:right]:
            inputs = row.get('inputs', {})
            if inputs.get('ena') != 1 or inputs.get('rst') == 1 or inputs.get('nReset') != 1:
                valid = False
                break
            enabled_edges += row.get('held', 1)

        if valid:
            expected = max(1, int(clk_cnt) // 4)
            observations.append((left, right, enabled_edges, expected, clk_cnt))

    if not observations:
        return (None, None, 'no complete enabled filter-sampling interval was observed')

    for left, right, actual, expected, clk_cnt in observations:
        if actual != expected:
            return (False, trace[right].get('edge'), f'filter_sample_tick interval was {actual} enabled edges for clk_cnt={clk_cnt}, expected max(1, clk_cnt//4)={expected}')

    return (True, trace[observations[-1][1]].get('edge'), 'filter_sample_tick intervals matched the clk_cnt-derived sampling interval')

def decide(trace):
    from specflow.refmodel.temporal import after, eventually, worst

    def activation(row):
        return (
            row.get('inputs', {}).get('cmd') == 1
            and row.get('outputs', {}).get('in_idle') == 1
        )

    def entered_start(row):
        return row.get('outputs', {}).get('in_start_sequence') == 1

    windows = after(
        trace,
        activation,
        until=entered_start,
    )

    return worst([
        eventually(
            window,
            entered_start,
            strong=True,
            after_activation=True,
        )
        for window in windows
    ])

def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    # The normalized encoding is authoritative: STOP == 2.  in_idle is
    # required so a held command does not reopen the window outside idle.
    starts = []
    for i, row in enumerate(trace):
        if (row.get('inputs', {}).get('cmd') == 2
                and row.get('inputs', {}).get('ena') == 1
                and out(row, 'in_idle') == 1):
            if i == 0 or not (
                trace[i - 1].get('inputs', {}).get('cmd') == 2
                and trace[i - 1].get('inputs', {}).get('ena') == 1
                and out(trace[i - 1], 'in_idle') == 1):
                starts.append(i)

    if not starts:
        return (None, None, 'STOP encoding 2 was not presented while the FSM was idle and enabled')

    for start in starts:
        low = None
        for i in range(start + 1, len(trace)):
            if out(trace[i], 'sda_oen') == 0 and out(trace[i - 1], 'sda_oen') != 0:
                low = i
                break

        if low is None:
            continue

        scl_released = None
        for i in range(low + 1, len(trace)):
            if out(trace[i], 'scl_oen') == 1:
                scl_released = i
                break

        if scl_released is None:
            continue

        for i in range(scl_released + 1, len(trace)):
            if out(trace[i], 'sda_oen') == 1 and out(trace[i - 1], 'sda_oen') == 0:
                return (True, trace[i]['edge'],
                        'STOP encoding 2 was accepted in idle and produced the required routed STOP distinction')

    return (False, trace[starts[0]]['edge'],
            'STOP encoding 2 was presented while idle, but no STOP-specific routed output sequence was observed')

def decide(trace):
    def out(row, name, default=0):
        return row.get('outputs', {}).get(name, default)

    def qualified(row, write):
        return (out(row, 'in_idle') == 1 and
                row.get('inputs', {}).get('ena') == 1 and
                ((row.get('inputs', {}).get('cmd') == 4) if write
                 else (row.get('inputs', {}).get('cmd') != 4)))

    positive = []
    negative = []
    for i, row in enumerate(trace):
        prev_pos = qualified(trace[i - 1], True) if i else False
        prev_neg = qualified(trace[i - 1], False) if i else False
        if qualified(row, True) and not prev_pos:
            positive.append(i)
        if qualified(row, False) and not prev_neg:
            negative.append(i)

    failures = []
    positive_seen = False
    negative_seen = False

    for start in positive:
        positive_seen = True
        left_idle = None
        for j in range(start + 1, len(trace)):
            if out(trace[j], 'in_idle') != 1:
                left_idle = j
                break
        if left_idle is None:
            failures.append((trace[start].get('edge'), 'WRITE was presented while idle but the FSM never accepted it'))
            continue

        ack = None
        for j in range(left_idle, len(trace)):
            if out(trace[j], 'cmd_ack') == 1:
                ack = j
                break
        if ack is None:
