def decide(trace):
    def inp(row, name):
        return row.get('inputs', {}).get(name)

    def sig(row, name):
        return row.get('outputs', {}).get(name)

    def reset(row):
        return inp(row, 'nReset') == 0 or inp(row, 'rst') == 1

    def probe(row, name):
        return sig(row, name) == 1

    # A raw SDA transition while enabled establishes that this requirement's
    # synchronization/filtering situation occurred.  It is not itself treated
    # as the value used by the design.
    activated = False
    previous_sda = None
    for row in trace:
        sda = inp(row, 'sda_i')
        if previous_sda is not None and sda != previous_sda and inp(row, 'ena') == 1:
            activated = True
            break
        previous_sda = sda

    if not activated:
        return (None, None, 'no enabled sda_i transition; synchronized/filtered SDA processing was not exercised')

    pending_busy = []
    pending_al = []
    pending_dout = []
    saw_evidence = False
    previous = None

    for row in trace:
        if previous is None:
            previous = row
            continue

        if reset(row):
            pending_busy = []
            pending_al = []
            pending_dout = []
            previous = row
            continue

        if inp(row, 'ena') == 1:
            if probe(row, 'start_condition'):
                pending_busy.append(1)
            if probe(row, 'stop_condition'):
                pending_busy.append(0)
            if probe(row, 'sda_arbitration_check') and probe(row, 'filtered_sda_low'):
                pending_al.append(1)
            if probe(row, 'filtered_scl_rising'):
                pending_dout.append(0 if probe(row, 'filtered_sda_low') else 1)

        edge = row.get('edge')
        if sig(row, 'busy') != sig(previous, 'busy'):
            saw_evidence = True
            if not pending_busy:
                return (False, edge, 'busy changed without a synchronized/filtered START or STOP event')
            expected = pending_busy.pop(0)
            if sig(row, 'busy') != expected:
                return (False, edge, 'busy did not reflect the synchronized/filtered START or STOP event')

        if sig(row, 'al') == 1 and sig(previous, 'al') != 1:
            saw_evidence = True
            if not pending_al:
                return (False, edge, 'al asserted without filtered SDA indicating arbitration loss')
            pending_al.pop(0)

        if sig(row, 'dout') != sig(previous, 'dout'):
            saw_evidence = True
            if not pending_dout:
                return (False, edge, 'dout changed without a filtered SCL rising-edge sample')
            expected = pending_dout.pop(0)
            if sig(row, 'dout') != expected:
                return (False, edge, 'dout did not capture the synchronized and filtered SDA value')

        previous = row

    if not saw_evidence:
        return (True, None, 'enabled raw SDA activity produced no unqualified downstream response')
    return (True, None, 'all observed SDA-derived responses were tied to synchronized and filtered events')

