        return any(
            earlier["edge"] in sda_falls
            and earlier["outputs"].get("filtered_scl_high") == 1
            and earlier["inputs"].get("ena") == 1
            for earlier in trace[:idx]
        )

    def sampling_opportunity(row):
        return row["outputs"].get("filter_sample_tick") == 1

    windows = after(
        trace,
        lambda row: start_context(row) and sampling_opportunity(row),
        until=TO_END,
    )
    return worst([
        eventually(
            window,
            lambda row: row["edge"] in busy_rises,
            strong=True,
            after_activation=False,
        )
        for window in windows
    ])

def decide(trace):
    def value(row, name, default=None):
        return row.get('outputs', {}).get(name, default)

    def busy_rise(i):
        if i <= 0:
            return False
        return (value(trace[i - 1], 'busy') == 0 and
                value(trace[i], 'busy') == 1)

    positive = []
    for i in range(1, len(trace)):
        # The declared filtered probes expose the majority-valued signals:
        # filtered_sda_low rising means majority SDA changed high to low,
        # while filtered_scl_high qualifies a START condition.
        if (value(trace[i - 1], 'filtered_sda_low') == 0 and
                value(trace[i], 'filtered_sda_low') == 1 and
                value(trace[i], 'filtered_scl_high') == 1):
            positive.append(i)

    negative = []
    i = 1
    while i < len(trace):
        raw_fall = (trace[i - 1].get('inputs', {}).get('sda_i') == 1 and
                    trace[i].get('inputs', {}).get('sda_i') == 0)
        if not raw_fall:
            i += 1
            continue

        j = i + 1
        while j < len(trace):
            if value(trace[j], 'filtered_scl_high') != 1:
                break
            if value(trace[j], 'filtered_sda_low') != 0:
                break
            raw_rise = (trace[j - 1].get('inputs', {}).get('sda_i') == 0 and
                        trace[j].get('inputs', {}).get('sda_i') == 1)
            if raw_rise:
                negative.append((i, j))
                break
            j += 1
        i = max(i + 1, j)

    for i in positive:
        if not any(busy_rise(k) for k in range(i, len(trace))):
            return (False, trace[i].get('edge'),
                    'after the filtered SDA majority changed low while filtered SCL stayed high, busy did not rise')

    for start, end in negative:
        if any(busy_rise(k) for k in range(start, end + 1)):
            return (False, trace[start].get('edge'),
                    'a raw SDA glitch returned before the three-sample majority changed, but busy rose')

    if positive or negative:
        return (True, None,
                'filtered majority transition caused busy to rise and short raw glitches caused no busy rise')
    return (None, None,
            'no filtered majority transition or complete short raw glitch was observed')

def decide(trace):
    def val(row, name):
        return row.get('outputs', {}).get(name,
               row.get('inputs', {}).get(name))

    def changed_at(i, port):
        return i > 0 and val(trace[i], port) != val(trace[i - 1], port)

    def return_index(start, port, baseline):
        for j in range(start + 1, len(trace)):
            if val(trace[j], port) == baseline:
                return j
        return None

    busy_glitch = []
    for i in range(1, len(trace)):
        if not changed_at(i, 'sda_i'):
            continue
        if not (val(trace[i], 'in_idle') == 1 and
                val(trace[i], 'filtered_scl_high') == 1 and
                val(trace[i], 'busy') == 0):
            continue
        baseline = val(trace[i - 1], 'sda_i')
        j = return_index(i, 'sda_i', baseline)
        if j is None:
            continue
        busy_glitch.append((i, j))

    dout_glitch = []
    for i in range(1, len(trace)):
        if not changed_at(i, 'scl_i'):
            continue
        if val(trace[i], 'in_read_sequence') != 1:
            continue
        filtered_sda = val(trace[i], 'filtered_sda_low')
        expected = 0 if filtered_sda == 1 else 1
        if val(trace[i], 'dout') == expected:
            continue
        baseline = val(trace[i - 1], 'scl_i')
        j = return_index(i, 'scl_i', baseline)
        if j is None:
            continue
        dout_glitch.append((i, j, val(trace[i], 'dout')))

    if not busy_glitch and not dout_glitch:
        return (None, None, 'no qualified short SDA or SCL glitch occurred')

    ordinary_busy = any(
        i > 0 and val(trace[i], 'start_condition') == 1 and
        val(trace[i - 1], 'busy') == 0 and val(trace[i], 'busy') == 1
        for i in range(len(trace))
    )
    ordinary_dout = any(
        i > 0 and val(trace[i], 'in_read_sequence') == 1 and
        val(trace[i], 'filtered_scl_rising') == 1 and
        val(trace[i], 'dout') != val(trace[i - 1], 'dout')
        for i in range(len(trace))
    )

    for i, j in busy_glitch:
        bad = next((k for k in range(i, j + 1)
                    if val(trace[k], 'busy') != 0), None)
        if bad is not None:
            return (False, trace[bad]['edge'],
                    'busy rose during a short SDA glitch; the glitch was not filtered')

    for i, j, previous in dout_glitch:
        bad = next((k for k in range(i, j + 1)
                    if val(trace[k], 'dout') != previous), None)
        if bad is not None:
            return (False, trace[bad]['edge'],
                    'dout changed during a short SCL glitch; the glitch produced a read capture')

    if busy_glitch and not ordinary_busy:
        return (None, trace[busy_glitch[0][0]]['edge'],
                'short SDA glitch was observed, but no ordinary filtered START response showed the required difference')
    if dout_glitch and not ordinary_dout:
        return (None, trace[dout_glitch[0][0]]['edge'],
                'short SCL glitch was observed, but no ordinary filtered READ capture showed the required difference')

    edges = []
    if busy_glitch:
        edges.append(trace[busy_glitch[0][0]]['edge'])
    if dout_glitch:
        edges.append(trace[dout_glitch[0][0]]['edge'])
    return (True, min(edges),
            'short glitches had no busy or dout effect while ordinary filtered responses were observed')

