    def value(row, port):
        return row['outputs'].get(port, row['inputs'].get(port))

    def start_applies(row):
        return (value(row, 'start_condition') == 1 and
                value(row, 'scl_i') == 1 and
                value(row, 'sda_i') == 0)

    def stop_detected(row):
        return value(row, 'stop_condition') == 1

