        trace,
        start_applies,
        until=stop_detected,
        aborts=reset_active,
    )

    verdicts = []
    for window in windows:
        rows = list(window.rows)
        if not rows:
            verdicts.append((None, window.edge,
                             'START-to-STOP window contains no observable states'))
            continue

        # effect_follows is true: do not require the registered status on the
        # START-detection row itself.
        candidate_rows = rows[1:]
        first_high = None
        for row in candidate_rows:
            if value(row, 'busy') == 1:
                first_high = row
                break

        if first_high is None:
            if not window.closed:
                verdicts.append((None, window.edge,
                                 'busy has not reached high before the trace ended; no STOP completed the window'))
            else:
                verdicts.append((False, window.edge,
                                 'busy never became high after the filtered START and before the filtered STOP'))
            continue

        bad = next((row for row in rows[rows.index(first_high):]
                    if value(row, 'busy') != 1), None)
        if bad is not None:
            verdicts.append((False, bad.get('edge'),
                             'busy fell before the filtered STOP condition'))
        elif not window.closed:
            verdicts.append((None, first_high.get('edge'),
                             'busy remained high in the observed portion, but no filtered STOP closed the window'))
        else:
            verdicts.append((True, first_high.get('edge'),
                             'busy reached high after START and remained high until STOP'))

    return worst(verdicts)

