    al_rises = edges(trace, "al", "rise")
    if not al_rises:
        return (None, None, "al never rose; arbitration loss did not occur in this trace")

    verdicts = []
    for al_edge in sorted(al_rises):
        al_pos = next((i for i, row in enumerate(trace)
                       if row.get("edge") == al_edge), None)
        if al_pos is None:
            continue

        idle_pos = None
        aborted = False
        for i in range(al_pos, len(trace)):
            inputs = trace[i].get("inputs", {})
            if inputs.get("nReset") == 0 or inputs.get("rst") == 1:
                aborted = True
                break
            outputs = trace[i].get("outputs", {})
            if outputs.get("in_idle") == 1:
                idle_pos = i
                break

        if aborted:
            verdicts.append((None, al_edge,
                             "arbitration-loss recovery was aborted by reset"))
            continue
        if idle_pos is None:
            verdicts.append((None, al_edge,
                             "arbitration loss occurred, but the trace ended before in_idle was reached"))
            continue

        row = trace[idle_pos]
        outputs = row.get("outputs", {})
        scl_released = outputs.get("scl_oen") == 1
        sda_released = outputs.get("sda_oen") == 1
        if not scl_released or not sda_released:
            missing = []
            if not scl_released:
                missing.append("scl_oen")
            if not sda_released:
                missing.append("sda_oen")
            verdicts.append((False, row.get("edge"),
                             "in_idle was reached after arbitration loss, but "
                             + ", ".join(missing) + " was not high"))
        else:
            verdicts.append((True, row.get("edge"),
                             "after arbitration loss, in_idle was reached and "
                             "scl_oen and sda_oen were high"))

    return worst(verdicts)

