    for i, expected, name in accepted:
        before = out(trace[i - 1], 'busy') if i > 0 else None
        for j in range(i, len(trace)):
            value = out(trace[j], 'busy')
            if value == expected:
                if before is not None and before != expected:
                    return (True, trace[j].get('edge'),
                            f'{name} was reflected by busy after filtering')
                # The state is already correct; the trace does not prove a
                # transition, but it does show the routed filtered state.
                return (True, trace[j].get('edge'),
                        f'{name} produced the expected busy state')
            if value is not None and value != before and before is not None:
                return (False, trace[j].get('edge'),
                        f'{name} produced busy={value}, expected {expected} after filtering')
        return (None, None, f'{name} was detected but the filtered busy response was not observed')

