        if end is None:
            continue
        if any(i <= k <= end and
               (out(trace[k], 'start_condition') == 1 or
                out(trace[k], 'stop_condition') == 1)
               for k in range(i, end + 1)):
            continue
        initial = out(trace[i - 1], 'busy')
