                inp(row, 'ena') == 1 and inp(row, 'scl_i') == 1 and
                inp(prev, 'sda_i') == 1 and inp(row, 'sda_i') == 0 and
                sig(prev, 'filtered_sda_low') == 0 and
                sig(prev, 'filtered_scl_high') == 1):
            trigger = i
            break

    if trigger is None:
        return (None, None, 'no post-reset stable SDA high-to-low transition with SCL high occurred')

    clk_cnt = inp(trace[trigger], 'clk_cnt')
    if not isinstance(clk_cnt, int):
        return (None, trace[trigger].get('edge'), 'clk_cnt was not available for the sampling-interval check')
    expected = max(1, clk_cnt >> 2)

    tick_rows = []
    busy_rise = None
    for i in range(trigger, len(trace)):
        row = trace[i]
        if inp(row, 'nReset') != 1 or inp(row, 'rst') != 0 or inp(row, 'ena') != 1:
