        if i > trigger and sig(trace[i - 1], 'busy') != 1 and sig(row, 'busy') == 1:
            busy_rise = i
            break

    if busy_rise is None:
        return (None, None, 'the resulting filtered START and busy rise were not observed')

    tick_rows = [i for i in tick_rows if i <= busy_rise]
    if len(tick_rows) < 2:
        return (None, trace[busy_rise].get('edge'), 'fewer than two filter samples were visible before busy rose')

    for a, b in zip(tick_rows, tick_rows[1:]):
        enabled_edges = sum(trace[j].get('held', 0) for j in range(a, b))
        if enabled_edges != expected:
            return (False, trace[b].get('edge'),
