    def reset_asserted(row):
        return inp(row, 'nReset') == 0 or inp(row, 'rst') == 1

    phase = None
    saw_disabled = False
    unresolved = False
    completed = False

    for row in trace:
        if reset_asserted(row):
            phase = None
            continue

        active = out(row, 'fsm_active') == 1
        enabled = inp(row, 'ena') == 1
        disabled = inp(row, 'ena') == 0

        if phase is None:
            if active and disabled:
                saw_disabled = True
                phase = 'disabled'
                if out(row, 'cmd_ack') == 1:
                    return (False, row.get('edge'),
                            'cmd_ack asserted while ena was low during an active command')
            continue

        if phase == 'disabled':
            if active and disabled:
                if out(row, 'cmd_ack') == 1:
                    return (False, row.get('edge'),
                            'cmd_ack asserted while ena was low during an active command')
            elif active and enabled:
                phase = 'enabled'
                if out(row, 'cmd_ack') == 1:
                    completed = True
                    phase = None
            elif not active:
                unresolved = True
                phase = None
            continue

        if phase == 'enabled':
            if enabled and out(row, 'cmd_ack') == 1:
                completed = True
                phase = None
            elif active and disabled:
                phase = 'disabled'
                if out(row, 'cmd_ack') == 1:
                    return (False, row.get('edge'),
                            'cmd_ack asserted while ena was low during an active command')
            elif not active:
                unresolved = True
                phase = None

    if phase is not None:
        unresolved = True

    if not saw_disabled:
        return (None, None,
                'no active command was observed with ena low and reset inactive')
    if unresolved:
        return (None, None,
                'cmd_ack remained low while ena was low, but the trace did not show '
                'the same active command re-enabled and completing')
    if not completed:
        return (None, None,
                'the disabled-side observation occurred, but no re-enabled completion '
                'was observed')
    return (True, None,
            'cmd_ack remained low while ena was low and asserted after the active '
            'command was re-enabled')

