        return (None, None, 'no output-interface observation occurred')

    for row in trace:
        outputs = row['outputs']
        edge = row['edge']

        if outputs.get('scl_o') != 0:
            return (False, edge, 'scl_o is high; the specification requires a constant low drive value')
        if outputs.get('sda_o') != 0:
            return (False, edge, 'sda_o is high; the specification requires a constant low drive value')

        scl_oen = outputs.get('scl_oen')
        if scl_oen not in (0, 1):
            return (False, edge, 'scl_oen is neither 0 (actively pulled low) nor 1 (released)')

        sda_oen = outputs.get('sda_oen')
        if sda_oen not in (0, 1):
            return (False, edge, 'sda_oen is neither 0 (actively pulled low) nor 1 (released)')

    return (True, None, 'scl_o and sda_o remained constant low; scl_oen and sda_oen used the declared active-low drive/release encoding')

