def decide(trace):
    from specflow.refmodel.temporal import after, eventually, worst

    sequence_probes = (
        'in_start_sequence',
        'in_stop_sequence',
        'in_read_sequence',
        'in_write_sequence',
    )

    def _sequence_active(row):
        outputs = row.get('outputs', {})
        return any(outputs.get(name) == 1 for name in sequence_probes)

    def _aborted(row):
        outputs = row.get('outputs', {})
        inputs = row.get('inputs', {})
        return (
            outputs.get('al') == 1
            or inputs.get('nReset') == 0
            or inputs.get('rst') == 1
        )

    windows = after(
        trace,
        _sequence_active,
        until=lambda row: row.get('outputs', {}).get('cmd_ack') == 1,
        aborts=_aborted,
    )

    verdicts = []
    for window in windows:
        ack_verdict = eventually(
            window,
            lambda row: row.get('outputs', {}).get('cmd_ack') == 1,
            strong=True,
        )
        if ack_verdict[0] is not True:
            verdicts.append(ack_verdict)
            continue

        ack_row = next(
            row for row in window.rows
            if row.get('outputs', {}).get('cmd_ack') == 1
        )
        ack_index = ack_row.get('index')
        ack_edge = ack_row.get('edge')
        high_edges = 0
        after_ack = False
        fell = False

        for row in trace:
            if not after_ack:
                if row.get('index') == ack_index:
                    after_ack = True
                    high_edges += row.get('held', 1)
                continue

            if row.get('outputs', {}).get('cmd_ack') == 1:
                high_edges += row.get('held', 1)
            else:
                fell = True
                break

        if high_edges != 1:
            verdicts.append((
                False,
                ack_edge,
                f'cmd_ack was high for {high_edges} clk cycle(s); expected exactly one',
            ))
        elif not fell:
            verdicts.append((
                False,
                ack_edge,
                'cmd_ack did not become low after the required one-cycle pulse',
            ))
        else:
            verdicts.append((
                True,
                ack_edge,
                'cmd_ack was high for exactly one clk cycle at sequence completion',
            ))

    return worst(verdicts)

def decide(trace):
    from specflow.refmodel.temporal import edges

    sequence_probes = (
        "in_start_sequence",
        "in_stop_sequence",
        "in_read_sequence",
        "in_write_sequence",
    )
    falling = {
        probe: edges(trace, probe, "fall")
        for probe in sequence_probes
    }

    terminal_rows = []
    for row in trace:
        inputs = row.get("inputs", {})
        outputs = row.get("outputs", {})
        if inputs.get("nReset") == 0 or inputs.get("rst") == 1:
            continue
        if outputs.get("al") == 1:
            continue
        if inputs.get("ena") != 1:
            continue
        if any(row.get("edge") in falling[probe] for probe in sequence_probes):
            terminal_rows.append(row)

    if not terminal_rows:
        return (None, None, "no non-aborted completed START, STOP, READ, or WRITE terminal state occurred")

    for row in terminal_rows:
        ack = row.get("outputs", {}).get("cmd_ack")
        if ack != 1:
            return (
                False,
                row.get("edge"),
                "cmd_ack was not asserted at the terminal phase; the obligation requires a one-clock-cycle acknowledge pulse"
            )
        if row.get("held") != 1:
            return (
                False,
                row.get("edge"),
                f"cmd_ack was asserted for {row.get('held')} clock edges at the terminal phase; the obligation requires exactly one clock cycle"
            )

    return (
        True,
        terminal_rows[-1].get("edge"),
        f"cmd_ack was asserted for exactly one clock cycle at each of {len(terminal_rows)} completed operation terminal state(s)"
    )

