    sda_changes = edges(trace, "sda_oen", "change")
    verdicts = []

    for window in windows:
        verdicts.append(
            eventually(
                window,
                lambda r: r.get("edge") in scl_changes,
                strong=True,
                after_activation=True,
            )
        )

        rows = window.rows
        is_start = any(out(r, "in_start_sequence") == 1 for r in rows)
        is_stop = any(out(r, "in_stop_sequence") == 1 for r in rows)
        is_read = any(out(r, "in_read_sequence") == 1 for r in rows)
        is_write = any(out(r, "in_write_sequence") == 1 for r in rows)

        if is_start or is_stop:
            verdicts.append(
                eventually(
                    window,
                    lambda r: r.get("edge") in sda_changes,
                    strong=True,
                    after_activation=True,
                )
            )
        elif is_read:
            verdicts.append(
                throughout(
                    window,
                    lambda r: out(r, "sda_oen") == 1,
                    after_activation=True,
                )
            )
        elif is_write:
            expected = 0 if window.value("din") == 0 else 1
            verdicts.append(
                throughout(
                    window,
                    lambda r, expected=expected: out(r, "sda_oen") == expected,
                    after_activation=True,
                )
            )

    return worst(verdicts)

