def decide(trace):
    activations = []
    previous_active = False

    for i, row in enumerate(trace):
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})
        enabled = inputs.get('ena') == 1
        active = outputs.get('fsm_active') == 1

        if enabled and active and not previous_active:
            activations.append(i)
        previous_active = active

    if not activations:
        return (None, None, 'no enabled accepted command transaction was observed')

    for start in activations:
        start_edge = trace[start].get('edge')
        al_at_start = trace[start].get('outputs', {}).get('al') == 1
        completed = False
        aborted = False
        ended = False

        for j in range(start + 1, len(trace)):
            row = trace[j]
            inputs = row.get('inputs', {})
            outputs = row.get('outputs', {})

            if inputs.get('nReset') == 0 or inputs.get('rst') == 1:
                ended = True
                break

            if outputs.get('cmd_ack') == 1:
                completed = True

            if outputs.get('al') == 1 and not al_at_start:
                aborted = True

            if outputs.get('fsm_active') != 1:
                ended = True
                if completed or aborted:
                    break
                return (False, row.get('edge'),
                        'accepted transaction returned inactive without cmd_ack or arbitration-loss indication')

        if completed or aborted:
            continue
        if not ended or (trace and trace[-1].get('outputs', {}).get('fsm_active') == 1):
            return (None, start_edge,
                    'accepted transaction remained active or the trace ended before its outcome')

    return (True, None,
            'each observed enabled command transaction produced cmd_ack or al')

def decide(trace):
    # The obligation does not constrain scl_oen for this broad activation.
    port = 'scl_oen'
    _observed = [row.get('outputs', {}).get(port) for row in trace]
    return (None, None, 'the obligation states supported capabilities but does not constrain scl_oen for this broad activation')

def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    def inp(row, name):
        return row.get('inputs', {}).get(name)

    def probe(row, name):
        return bool(out(row, name))

    def rising(name, i):
        return probe(trace[i], name) and (i == 0 or not probe(trace[i - 1], name))

    def span_from(i, name):
        indices = []
        for k in range(i, len(trace)):
            if not probe(trace[k], name):
                break
            indices.append(k)
        return indices

    failures = []
    undecided = []
    saw_activation = False

    sequences = [
        ('in_start_sequence', 'START'),
        ('in_stop_sequence', 'STOP'),
        ('in_write_sequence', 'WRITE'),
        ('in_read_sequence', 'READ'),
    ]

    for probe_name, label in sequences:
        for i, row in enumerate(trace):
            if not rising(probe_name, i):
                continue
            if inp(row, 'ena') != 1 or inp(row, 'nReset') == 0 or inp(row, 'rst') == 1:
                continue

            saw_activation = True
            indices = span_from(i, probe_name)
            if not indices:
                continue

            ack_positions = [k for k in indices if out(trace[k], 'cmd_ack') == 1]
            aborted = any(out(trace[k], 'al') == 1 for k in indices)
            if not aborted and not ack_positions:
                if indices[-1] == len(trace) - 1:
                    undecided.append((trace[i]['edge'], label + ' command was active but the trace ended before completion'))
                else:
                    failures.append((trace[i]['edge'], label + ' command completed without cmd_ack'))

            if label == 'START':
                low_sda = [k for k in indices if out(trace[k], 'sda_oen') == 0 and out(trace[k], 'scl_oen') == 1]
                low_scl = [k for k in indices if out(trace[k], 'scl_oen') == 0]
                if not low_sda or not low_scl or low_sda[0] >= low_scl[0]:
                    failures.append((trace[i]['edge'], 'START did not drive SDA low before pulling SCL low'))

            elif label == 'STOP':
                low_sda = [k for k in indices if out(trace[k], 'sda_oen') == 0]
                released_scl = [k for k in indices if out(trace[k], 'scl_oen') == 1]
                released_sda = [k for k in indices if out(trace[k], 'sda_oen') == 1]
                if not low_sda or not released_scl or not released_sda:
                    failures.append((trace[i]['edge'], 'STOP did not contain the required SDA-low, SCL-release, and SDA-release phases'))
                elif not (low_sda[0] < released_scl[0] < released_sda[0]):
                    failures.append((trace[i]['edge'], 'STOP phases occurred in the wrong order'))

            elif label == 'WRITE':
                desired_sda_oen = 1 if inp(row, 'din') == 1 else 0
                bit_phase = [k for k in indices if out(trace[k], 'scl_oen') == 1 and out(trace[k], 'sda_oen') == desired_sda_oen]
                scl_low_after = [k for k in indices if bit_phase and k > bit_phase[0] and out(trace[k], 'scl_oen') == 0]
                if not bit_phase or not scl_low_after:
                    failures.append((trace[i]['edge'], 'WRITE did not present the din-selected SDA bit during the released SCL phase'))

            elif label == 'READ':
                if not any(out(trace[k], 'sda_oen') == 1 and out(trace[k], 'scl_oen') == 1 for k in indices):
                    failures.append((trace[i]['edge'], 'READ did not release SDA during the released SCL phase'))

    for i, row in enumerate(trace):
        if inp(row, 'ena') != 1 or inp(row, 'nReset') == 0 or inp(row, 'rst') == 1:
            continue

        if probe(row, 'start_condition') and (i == 0 or not probe(trace[i - 1], 'start_condition')):
            saw_activation = True
            if not any(out(trace[k], 'busy') == 1 for k in range(i, len(trace))):
                failures.append((row['edge'], 'filtered START occurred without busy becoming asserted'))

        if probe(row, 'stop_condition') and (i == 0 or not probe(trace[i - 1], 'stop_condition')):
            saw_activation = True
            if not any(out(trace[k], 'busy') == 0 for k in range(i, len(trace))):
                failures.append((row['edge'], 'filtered STOP occurred without busy clearing'))

        if probe(row, 'sda_arbitration_check') and inp(row, 'sda_i') == 0:
            saw_activation = True
            if not any(out(trace[k], 'al') == 1 for k in range(i, len(trace))):
                failures.append((row['edge'], 'arbitration-check condition with SDA low did not assert al'))

    if failures:
        edge, detail = failures[0]
        return (False, edge, detail)
    if not saw_activation:
        return (None, None, 'no enabled command sequence or relevant filtered bus condition occurred')
    if undecided:
        edge, detail = undecided[0]
        return (None, edge, detail)
    return (True, None, 'all exercised enabled command and filtered-bus capabilities satisfied their declared output obligations')

def decide(trace):
    def out(row, name, default=None):
        return row.get('outputs', {}).get(name, default)

    def reset_active(row):
        inputs = row.get('inputs', {})
        return inputs.get('nReset') == 0 or inputs.get('rst') == 1

    starts = []
    was_active = False
    for i, row in enumerate(trace):
        active = out(row, 'fsm_active', 0) == 1
        if active and not was_active and row.get('inputs', {}).get('ena') == 1:
            starts.append(i)
        was_active = active

    if not starts:
        return (None, None, 'no enabled live command transaction was observed')

    for start in starts:
        start_edge = trace[start].get('edge')
        al_at_start = out(trace[start], 'al', 0) == 1
        completed = False
        aborted = False
        ended = False

        for j in range(start, len(trace)):
            row = trace[j]
            if reset_active(row):
                ended = True
                break

            al_now = out(row, 'al', 0) == 1
            if al_now and not al_at_start:
                aborted = True
                break

            ack_now = out(row, 'cmd_ack', 0) == 1
            ack_rise = (j > 0 and ack_now and
                        out(trace[j - 1], 'cmd_ack', 0) != 1)
            if ack_rise:
                held = row.get('held', 1)
                if held != 1:
                    return (False, row.get('edge'),
                            f'cmd_ack completion pulse held for {held} edges, but the declared port contract requires one clock')
                completed = True
                break

            if j > start and out(row, 'fsm_active', 0) != 1:
                ended = True
                break

        if aborted or completed:
            continue
        if ended:
            return (False, trace[start].get('edge'),
                    'live command transaction ended without cmd_ack or arbitration-loss indication')
        return (None, start_edge,
                'live command transaction remained open or the trace ended before completion')

    return (True, None,
            'every observed enabled command transaction completed with a one-clock cmd_ack pulse or was aborted by arbitration loss')

def decide(trace):
    def value(row, port, default=0):
        return row.get('outputs', {}).get(port, default)

    def reset(row):
        ins = row.get('inputs', {})
        return ins.get('nReset') == 0 or ins.get('rst') == 1

    sequence_probes = (
        'in_start_sequence',
        'in_stop_sequence',
        'in_write_sequence',
        'in_read_sequence',
    )

    # A declared sequence probe transition identifies command-specific
    # activity.  ena qualifies that activity; it is not itself the expected
    # output behaviour.
    activations = []
    for i, row in enumerate(trace):
        if reset(row) or row.get('inputs', {}).get('ena') != 1:
            continue
        previous = trace[i - 1] if i else None
        for probe in sequence_probes:
            now = value(row, probe) == 1
            before = previous is not None and value(previous, probe) == 1
            if now and not before:
                activations.append(i)
                break

    if not activations:
        return (None, None,
                'no enabled declared START, STOP, WRITE, or READ sequence was observed')

    # The requirement gives no response latency or state-count deadline.
    # Search forward for command completion rather than naming a positional
    # successor state.  Arbitration loss or reset ends that command's promise.
    for start in activations:
        baseline_al = value(trace[start], 'al') == 1
        for i in range(start, len(trace)):
            row = trace[i]
            if reset(row):
                break
            if value(row, 'al') == 1 and not baseline_al:
                break
            if value(row, 'cmd_ack') == 1:
                return (True, row.get('edge'),
                        'command-specific activity reached the declared cmd_ack completion indication')

    return (None, trace[activations[0]].get('edge'),
            'command-specific activity was observed, but this trace ended without observable command completion')

