def decide(trace):
    probes = (
        'in_idle', 'fsm_active', 'in_start_sequence', 'in_stop_sequence',
        'in_read_sequence', 'in_write_sequence'
    )

    def in_reached_state(row):
        outputs = row.get('outputs', {})
        return any(outputs.get(p) == 1 for p in probes)

    observations = []
    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        if not in_reached_state(row):
            continue
        po = prev.get('outputs', {})
        oo = row.get('outputs', {})
        inp = row.get('inputs', {})

        for oen, line in (('scl_oen', 'scl_i'), ('sda_oen', 'sda_i')):
            before = po.get(oen)
            after = oo.get(oen)
            if before == after or before is None or after is None:
                continue
            line_value = inp.get(line)
            observations.append((row, oen, line, after, line_value))

    if not observations:
        return (None, None, 'no clocked output-enable drive or release occurred in a reached declared state')

    for row, oen, line, value, line_value in observations:
        expected = 0 if value == 0 else 1
        if line_value != expected:
            action = 'pulled low' if value == 0 else 'released high for the external pull-up'
            return (
                False,
                row.get('edge'),
                f'{oen} changed to {value}, but {line} was {line_value}; expected {line} {action}'
            )

