def decide(trace):
    from specflow.refmodel.temporal import after, eventually, throughout, worst

    supported = {1, 2, 4, 8}

    def active_command(row):
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})
        return (
            inputs.get('cmd') in supported
            and inputs.get('nReset') == 1
            and inputs.get('rst') == 0
            and outputs.get('fsm_active') == 1
        )

    def ended(row):
        return row.get('outputs', {}).get('fsm_active') == 0

    windows = after(trace, active_command, until=ended)
    if not windows:
        return (None, None, 'no supported command reached the declared fsm_active state')

    scl_changes = {
        r['edge'] for i, r in enumerate(trace)
        if i > 0 and r.get('outputs', {}).get('scl_oen') != trace[i - 1].get('outputs', {}).get('scl_oen')
    }
    sda_changes = {
        r['edge'] for i, r in enumerate(trace)
        if i > 0 and r.get('outputs', {}).get('sda_oen') != trace[i - 1].get('outputs', {}).get('sda_oen')
    }

    verdicts = []
    for window in windows:
        verdicts.append(
            throughout(
                window,
                lambda r: (
                    r.get('outputs', {}).get('scl_o') == 0
                    and r.get('outputs', {}).get('sda_o') == 0
                ),
            )
        )
        verdicts.append(
            eventually(
                window,
                lambda r: (
                    r['edge'] in scl_changes or r['edge'] in sda_changes
                ),
                strong=False,
            )
        )

    return worst(verdicts)

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, eventually, throughout, worst

    active_rises = edges(trace, "fsm_active", "rise")
    windows = after(
        trace,
        lambda r: r["edge"] in active_rises,
        until=lambda r: r["outputs"].get("fsm_active") == 0
    )

    def boundary_outputs_low(r):
        outputs = r["outputs"]
        return (
            outputs.get("scl_o") == 0 and
            outputs.get("sda_o") == 0 and
            outputs.get("sda_oen") in (0, 1)
        )

    verdicts = []
    for w in windows:
        verdicts.append(
            throughout(w, boundary_outputs_low, after_activation=False)
        )
        verdicts.append(
            eventually(
                w,
                lambda r: r["outputs"].get("scl_oen") == 0,
                strong=False,
                after_activation=False
            )
        )
        verdicts.append(
            eventually(
                w,
                lambda r: r["outputs"].get("scl_oen") == 1,
                strong=False,
                after_activation=False
            )
        )

    return worst(verdicts)

def decide(trace):
    observed_ports = ("scl_o", "scl_oen", "sda_o", "sda_oen")
    command_seen = False
    for row in trace:
        if row.get("inputs", {}).get("cmd") in (1, 2, 4, 8):
            command_seen = True
            # These are the declared observable ports for this requirement.
            # The obligation states no particular value or transition to assert.
            _ = tuple(row.get("outputs", {}).get(port) for port in observed_ports)
