def decide(trace):
    def value(row, section, name):
        return row.get(section, {}).get(name)

    def held(row):
        return row.get('held', 1)

    # Find observed rising events of the declared filter-sampling indicator.
    events = []
    previous = False
    for i, row in enumerate(trace):
        current = bool(value(row, 'outputs', 'filter_sample_tick'))
        if current and not previous:
            events.append(i)
        previous = current

    observations = []
    for left, right in zip(events, events[1:]):
        left_cnt = value(trace[left], 'inputs', 'clk_cnt')
        right_cnt = value(trace[right], 'inputs', 'clk_cnt')
        if left_cnt is None or left_cnt != right_cnt:
            continue

        valid = True
        duration = 0
        for row in trace[left:right]:
            if (value(row, 'inputs', 'ena') != 1 or
                    value(row, 'inputs', 'rst') == 1 or
                    value(row, 'inputs', 'nReset') != 1 or
                    value(row, 'inputs', 'clk_cnt') != left_cnt):
                valid = False
                break
            duration += held(row)

        if valid and duration > 0:
            observations.append((left_cnt, duration, right))

    groups = {}
    for clk_cnt, duration, right in observations:
        groups.setdefault(clk_cnt, []).append((duration, right))

    counts = sorted(groups)
    comparisons = []
    for lower_pos, lower in enumerate(counts):
        for higher in counts[lower_pos + 1:]:
            lower_durations = [item[0] for item in groups[lower]]
            higher_durations = [item[0] for item in groups[higher]]
            lower_mean_num = sum(lower_durations)
            higher_mean_num = sum(higher_durations)
            comparisons.append((
                lower, higher,
                lower_mean_num, len(lower_durations),
                higher_mean_num, len(higher_durations),
                max(item[1] for item in groups[higher])
            ))

    if not comparisons:
        return (None, None,
                'no complete enabled filter-sampling intervals were observed for two distinct clk_cnt values')

    for lower, higher, lower_sum, lower_n, higher_sum, higher_n, edge in comparisons:
        # Compare averages without introducing floating-point assumptions.
        if higher_sum * lower_n < lower_sum * higher_n:
            return (
                False,
                trace[edge].get('edge'),
                f'filter-sample intervals shortened when clk_cnt increased from {lower} to {higher}; '
                'the sampling interval must be derived monotonically from the clock prescale value'
            )

    return (
        True,
        trace[comparisons[-1][6]].get('edge'),
        'observed filter-sampling intervals were nondecreasing as clk_cnt increased; '
        'no exact interval count was assumed because the requirement does not state one'
    )

