def decide(trace):
    def out(row, name, default=0):
        return row.get('outputs', {}).get(name, default)

    def qualified(row, write):
        return (out(row, 'in_idle') == 1 and
                row.get('inputs', {}).get('ena') == 1 and
                ((row.get('inputs', {}).get('cmd') == 4) if write
                 else (row.get('inputs', {}).get('cmd') != 4)))

    positive = []
    negative = []
    for i, row in enumerate(trace):
        prev_pos = qualified(trace[i - 1], True) if i else False
        prev_neg = qualified(trace[i - 1], False) if i else False
        if qualified(row, True) and not prev_pos:
            positive.append(i)
        if qualified(row, False) and not prev_neg:
            negative.append(i)

    failures = []
    positive_seen = False
    negative_seen = False

    for start in positive:
        positive_seen = True
        left_idle = None
        for j in range(start + 1, len(trace)):
            if out(trace[j], 'in_idle') != 1:
                left_idle = j
                break
        if left_idle is None:
            failures.append((trace[start].get('edge'), 'WRITE was presented while idle but the FSM never accepted it'))
            continue

        ack = None
        for j in range(left_idle, len(trace)):
            if out(trace[j], 'cmd_ack') == 1:
                ack = j
                break
        if ack is None:
            failures.append((trace[left_idle].get('edge'), 'supported WRITE command produced no cmd_ack completion pulse'))
        elif trace[ack].get('held') != 1:
            failures.append((trace[ack].get('edge'), 'WRITE cmd_ack was not high for exactly one clock'))

    for start in negative:
        negative_seen = True
        for j in range(start, len(trace)):
            if not qualified(trace[j], False):
                break
            if out(trace[j], 'cmd_ack') == 1:
                failures.append((trace[j].get('edge'), 'idle unsupported command produced a WRITE completion pulse'))
                break

    if failures:
        edge, detail = failures[0]
        return (False, edge, detail)
    if not positive_seen or not negative_seen:
        return (None, None, 'the trace does not show both WRITE support and the idle unsupported-command contrast')
    return (True, None, 'WRITE produces a one-clock cmd_ack completion pulse, while unsupported idle commands produce none')

