    if bad:
        return (False, bad[0].get('edge'), 'cmd_ack was not a one-clock completion pulse for the supported WRITE command')

    if len(ack_rows) != 1:
        return (False, ack_rows[1].get('edge'), 'cmd_ack produced more than one completion pulse for the supported WRITE command')

    return (True, ack_rows[0].get('edge'), 'supported WRITE command completed with one cmd_ack clock')

