from specflow.refmodel.temporal import WHILE_ACTIVE, after, edges, throughout, worst


def decide(trace):
    def out(row, name, default=0):
        return row.get('outputs', {}).get(name, default)

    # REQ-0125 route: read sampling must occur on the accepted filtered
    # SCL rising edge, not on the raw scl_i transition.
    def accepted_sample(row):
        return (
            out(row, 'in_read_sequence') == 1
            and out(row, 'sda_oen') == 1
            and out(row, 'filtered_scl_rising') == 1
        )

    def sampled_value(row):
        expected = 0 if out(row, 'filtered_sda_low') == 1 else 1
        return out(row, 'dout') == expected

    sample_windows = after(
        trace,
        accepted_sample,
        until=WHILE_ACTIVE,
    )
    verdicts = [
        throughout(w, sampled_value, after_activation=False)
        for w in sample_windows
    ]

    # A raw SCL rising edge that is not accepted by synchronization/filtering
    # must not update dout during the released read window.
    raw_rises = edges(trace, 'scl_i', 'rise')
    raw_glitch_seen = False
    for i, row in enumerate(trace):
        if (
            row.get('edge') in raw_rises
            and out(row, 'in_read_sequence') == 1
            and out(row, 'sda_oen') == 1
            and out(row, 'filtered_scl_rising') != 1
        ):
            raw_glitch_seen = True
            if i > 0 and out(row, 'dout') != out(trace[i - 1], 'dout'):
                return (False, row.get('edge'), 'dout changed on a raw scl_i rising edge that was not a filtered SCL rising edge')

    if not sample_windows and not raw_glitch_seen:
        return (None, None, 'no released read-window SCL sampling or rejected raw SCL transition occurred')

    if raw_glitch_seen:
        verdicts.append((True, None, 'dout remained unchanged for rejected raw scl_i rising transition(s)'))

    result = worst(verdicts)
    if result[0] is False:
        return result
    if sample_windows:
        return (True, None, 'dout sampled the filtered SDA value on each accepted filtered SCL rising edge')
    return result

