        until=any_of([{'al': 1}, {'cmd_ack': 1}]),
        aborts=aborts
    )
    high_windows = after(
        trace,
        lambda r: enabled_check(r) and r['outputs'].get('filtered_sda_low') == 0,
        until=holds({'cmd_ack': 1}),
