    probes = (
        'in_start_sequence',
        'in_stop_sequence',
        'in_read_sequence',
        'in_write_sequence',
    )

    def value(row, name):
        return row.get('outputs', {}).get(name)

    def reset_or_abort(row):
        return (
            value(row, 'al') == 1 or
            row.get('inputs', {}).get('nReset') == 0 or
            row.get('inputs', {}).get('rst') == 1
        )

    def in_command_sequence(row):
        return any(value(row, probe) == 1 for probe in probes)

    starts = []
    for i, row in enumerate(trace):
        if row.get('inputs', {}).get('ena') != 1:
            continue
        if reset_or_abort(row):
            continue
        current = in_command_sequence(row)
        previous = in_command_sequence(trace[i - 1]) if i > 0 else False
        if current and not previous:
            starts.append(i)

    if not starts:
        return (None, None, 'no accepted START, STOP, READ, or WRITE command sequence was observed')

    results = []
    for start in starts:
        ack_index = None
        aborted = False

        for j in range(start + 1, len(trace)):
            row = trace[j]
            if reset_or_abort(row):
                aborted = True
                break
            if value(row, 'cmd_ack') == 1:
                ack_index = j
                break

        if aborted:
            results.append((None, trace[start].get('edge'), 'command sequence was aborted by reset or arbitration loss'))
            continue

        if ack_index is None:
            results.append((False, trace[start].get('edge'), 'command completed without cmd_ack; required to assert for exactly one clock cycle'))
            continue

        high_edges = 0
        k = ack_index
        while k < len(trace) and value(trace[k], 'cmd_ack') == 1:
            high_edges += trace[k].get('held', 1)
            k += 1

        if high_edges != 1:
            results.append((False, trace[ack_index].get('edge'), f'cmd_ack was high for {high_edges} clock cycle(s), expected exactly one'))
        else:
            results.append((True, trace[ack_index].get('edge'), 'cmd_ack asserted for exactly one clock cycle at command completion'))

    for result in results:
        if result[0] is False:
            return result
    for result in results:
        if result[0] is None:
            return result
    return (True, None, 'each observed command completion had a one-clock-cycle cmd_ack pulse')

