            window,
            lambda r: r['outputs'].get('cmd_ack') != 1,
            after_activation=True,
        )
        if no_ack[0] is False:
            verdicts.append((False, no_ack[1], 'cmd_ack asserted while slave_wait was active; completion was not postponed during SCL stretch'))
            continue
        if no_ack[0] is None:
