        if not rows:
            verdicts.append((None, window.edge, 'slave_wait window contained no decidable states'))
            continue
        start = max(r['index'] for r in rows)
        command = rows[0]['inputs'].get('cmd')
        completion = None
        for r in trace:
            if r['index'] <= start:
                continue
            if r['inputs'].get('nReset') == 0 or r['inputs'].get('rst') == 1:
                break
            if r['inputs'].get('cmd') != command or r['inputs'].get('ena') != 1:
                break
            if (r['outputs'].get('scl_oen') == 1
