def decide(trace):
    from specflow.refmodel.temporal import after, edges, throughout, worst

    def out(row, name):
        return row.get('outputs', {}).get(name)

    release_edges = edges(trace, 'scl_oen', 'rise')

    def recognized_active(row):
        return (
            out(row, 'fsm_active') == 1 and
            any(out(row, name) == 1 for name in (
                'in_start_sequence',
                'in_stop_sequence',
                'in_read_sequence',
                'in_write_sequence'))
        )

    def opens(row):
        return (
            row.get('edge') in release_edges and
            recognized_active(row) and
            row.get('inputs', {}).get('ena') == 1 and
            row.get('inputs', {}).get('scl_i') == 0 and
            out(row, 'filtered_scl_high') == 0
        )

    def filtered_scl_high(row):
        return out(row, 'filtered_scl_high') == 1

    windows = after(trace, opens, until=filtered_scl_high)
    if not windows:
        return (None, None, 'no enabled active-command SCL-stretch interval occurred')

    low_verdicts = [
        throughout(
            window,
            lambda row: out(row, 'cmd_ack') == 0,
            after_activation=False)
        for window in windows
    ]
    low_result = worst(low_verdicts)
    if low_result[0] is False:
        return low_result

    completion_seen = False
    completion_edge = None
    for window in windows:
        if not window.rows:
            continue
        close_index = window.rows[-1].get('index')
        for row in trace:
            if row.get('index', -1) >= close_index and out(row, 'cmd_ack') == 1:
                completion_seen = True
                completion_edge = row.get('edge')
                break
        if completion_seen:
            break

    if not completion_seen:
        return (None, None, 'slave-wait interval was observed and cmd_ack stayed low, but no later completion was observed')

    return (True, completion_edge, 'cmd_ack remained low while released SCL was filtered low and was observed only after filtered SCL became high')

