def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, eventually, throughout, worst

    def input_holds(row, cond):
        return all(row.get('inputs', {}).get(port) == value
                   for port, value in cond.items())

    def output_holds(row, cond):
        return all(row.get('outputs', {}).get(port) == value
                   for port, value in cond.items())

    def any_input_holds(conditions):
        return lambda row: any(input_holds(row, cond) for cond in conditions)

    # The probe identifies the precise slave-wait situation.  cmd is not used:
    # the contract supplies no authoritative symbolic encoding table.
    applies = lambda row: (
        input_holds(row, {'ena': 1})
        and output_holds(row, {'slave_wait_active': 1})
    )
    released = lambda row: output_holds(row, {'filtered_scl_high': 1})
    aborted = any_input_holds([
        {'nReset': 0},
        {'rst': 1},
    ])

    wait_windows = after(
        trace,
        applies,
        until=released,
        aborts=aborted,
    )
    if not wait_windows:
        return (None, None, 'slave_wait_active never opened')

    paused = worst([
        throughout(
            window,
            lambda row: output_holds(row, {'scl_oen': 1}),
            after_activation=True,
        )
        for window in wait_windows
    ])
    if paused[0] is False:
        return paused

    # For each completed wait window, use the actual filtered-SCL rising
    # transition that closed it, then require the routed observable to reach
    # the next SCL-low phase without imposing a cycle count.
    rising_edges = edges(trace, 'filtered_scl_high', 'rise')
    release_edges = set()
    for window in wait_windows:
        if window.closed:
            for row in window.rows:
                if row['edge'] in rising_edges:
                    release_edges.add(row['edge'])

    if not release_edges:
        return paused if paused[0] is False else (None, None,
            'slave_wait did not reach an observed SCL release')

    resumed_windows = after(
        trace,
        lambda row: row['edge'] in release_edges,
        until=TO_END,
    )
    resumed = worst([
        eventually(
            window,
            lambda row: output_holds(row, {'scl_oen': 0}),
            strong=True,
            after_activation=True,
        )
        for window in resumed_windows
    ])
    return worst([paused, resumed])

