def decide(trace):
    def holds(cond):
        def predicate(row):
            vals = {}
            vals.update(row.get('inputs', {}))
            vals.update(row.get('outputs', {}))
            return all(vals.get(port) == value for port, value in cond.items())
        return predicate

    def any_of(alternatives):
        predicates = [holds(condition) for condition in alternatives]
        return lambda row: any(predicate(row) for predicate in predicates)

    try:
        from specflow.refmodel.temporal import TO_END, after, throughout, worst
    except Exception:
        return (None, None, 'temporal operators unavailable')

    opens = lambda row: (
        row.get('inputs', {}).get('ena') == 1
        and row.get('outputs', {}).get('slave_wait_active') == 1
    )
    releases = holds({'filtered_scl_high': 1})
    aborts = any_of([{'nReset': 0}, {'rst': 1}])

    windows = after(trace, opens, until=releases, aborts=aborts)
    if not windows:
        return (None, None, 'slave_wait_active never occurred')

    verdicts = []
    for window in windows:
        verdict = throughout(
            window,
            lambda row: row.get('outputs', {}).get('scl_oen') == 1,
            after_activation=True
        )
        if verdict[0] is False:
            return verdict
        if verdict[0] is None:
            verdicts.append(verdict)
            continue

        start = next((i for i, row in enumerate(trace)
                      if row.get('edge') == window.edge), None)
        if start is None:
            verdicts.append((None, window.edge, 'cannot locate slave-wait window'))
            continue

        release_i = next((i for i in range(start, len(trace))
                          if releases(trace[i])), None)
        if release_i is None or not getattr(window, 'closed', False):
            verdicts.append((None, window.edge,
                             'SCL was not observed released; paused phase is incomplete'))
            continue

        resumed = None
        for i in range(max(start + 1, release_i), len(trace)):
            before = trace[i - 1].get('outputs', {}).get('scl_oen')
            now = trace[i].get('outputs', {}).get('scl_oen')
            if before == 1 and now == 0:
                resumed = trace[i]
                break

        if resumed is None:
            verdicts.append((None, trace[release_i].get('edge'),
                             'slave-wait occurred, but post-release SCL-low advancement was not observed'))
        else:
            verdicts.append((True, resumed.get('edge'),
                             'scl_oen stayed released throughout slave-wait and changed low only after SCL release'))

    return worst(verdicts)

