def decide(trace):
    def reset(row):
        ins = row.get('inputs', {})
        return ins.get('nReset') == 0 or ins.get('rst') == 1

    def value(row, name):
        return row.get('outputs', {}).get(name)

    def raw_changed(previous, current):
        return (previous.get('inputs', {}).get('scl_i') != current.get('inputs', {}).get('scl_i') or
                previous.get('inputs', {}).get('sda_i') != current.get('inputs', {}).get('sda_i'))

    checked = False
    last_raw_change = None
    episode_start = 0

    for i, row in enumerate(trace):
        if reset(row):
            last_raw_change = None
            episode_start = i + 1
            continue

        if i > episode_start and raw_changed(trace[i - 1], row):
            last_raw_change = i

        start = value(row, 'start_condition') == 1
        stop = value(row, 'stop_condition') == 1
        prior_start = i > 0 and value(trace[i - 1], 'start_condition') == 1
        prior_stop = i > 0 and value(trace[i - 1], 'stop_condition') == 1

        condition = None
        expected_busy = None
        if start and not prior_start:
            condition = 'START'
            expected_busy = 1
        elif stop and not prior_stop:
            condition = 'STOP'
            expected_busy = 0

        if condition is None:
            continue

        checked = True
        begin = last_raw_change if last_raw_change is not None else episode_start
        baseline = value(trace[begin - 1], 'busy') if begin > episode_start else value(row, 'busy')

        for j in range(begin, i):
            if value(trace[j], 'busy') != baseline:
                return (False, trace[j]['edge'],
                        f'busy changed before the synchronized and filtered {condition} condition; '
                        'the raw scl_i/sda_i transition was not allowed to take effect immediately')

        if value(row, 'busy') != expected_busy:
            return (False, row['edge'],
                    f'busy was {value(row, "busy")} when the synchronized and filtered {condition} condition was reached; '
                    f'expected busy == {expected_busy}')

    if not checked:
        return (None, None, 'no synchronized START or STOP condition occurred in this trace')

    return (True, None,
            'busy remained unchanged before each synchronized and filtered START/STOP condition '
            'and had the required value when the condition was reached')

