        return row.get('inputs', {}).get('nReset') == 0 or row.get('inputs', {}).get('rst') == 1

    if not trace:
        return (None, None, 'no sampling states; the synchronization situation never occurred')

    failures = []
    saw_condition = False
    saw_valid_row = False
    previous = None

    for row in trace:
        if reset(row):
            previous = None
            saw_valid_row = False
            continue

        start = bool(out(row, 'start_condition'))
        stop = bool(out(row, 'stop_condition'))
        previous_start = bool(out(previous, 'start_condition')) if previous is not None else False
        previous_stop = bool(out(previous, 'stop_condition')) if previous is not None else False

        if previous is not None and saw_valid_row:
            busy_changed = out(row, 'busy') != out(previous, 'busy')
            raw_changed = (
                row.get('inputs', {}).get('scl_i') != previous.get('inputs', {}).get('scl_i') or
                row.get('inputs', {}).get('sda_i') != previous.get('inputs', {}).get('sda_i')
            )
            if raw_changed and busy_changed and not (start or stop):
                failures.append((row.get('edge'), 'busy changed on a raw scl_i/sda_i transition before a synchronized filtered START or STOP condition'))

        if start and not previous_start:
            saw_condition = True
            if previous is None or out(row, 'busy') != 1 or out(previous, 'busy') == 1:
                failures.append((row.get('edge'), 'busy did not rise when the synchronized filtered START condition was reached'))

        if stop and not previous_stop:
