            if previous is None or out(row, 'busy') != 0 or out(previous, 'busy') == 0:
                failures.append((row.get('edge'), 'busy did not fall when the synchronized filtered STOP condition was reached'))

        previous = row
        saw_valid_row = True

    if not saw_condition:
        return (None, None, 'no synchronized filtered START or STOP condition occurred in this trace')
    if failures:
        edge, detail = failures[0]
