from specflow.refmodel.temporal import TO_END, after, edges, eventually, worst

def decide(trace):
    sda_falls = edges(trace, "sda_i", "fall")
    busy_rises = edges(trace, "busy", "rise")

    def start_context(row):
        if row["inputs"].get("ena") != 1:
            return False
        if row["outputs"].get("filtered_scl_high") != 1:
            return False
        if row["outputs"].get("busy") != 0:
            return False
        idx = row["index"]
        return any(
            earlier["edge"] in sda_falls
            and earlier["outputs"].get("filtered_scl_high") == 1
            and earlier["inputs"].get("ena") == 1
            for earlier in trace[:idx]
        )

    def sampling_opportunity(row):
        return row["outputs"].get("filter_sample_tick") == 1

    windows = after(
        trace,
        lambda row: start_context(row) and sampling_opportunity(row),
        until=TO_END,
    )
    return worst([
        eventually(
            window,
            lambda row: row["edge"] in busy_rises,
            strong=True,
            after_activation=False,
        )
        for window in windows
    ])

