def decide(trace):
    def out(row, name, default=0):
        return row.get('outputs', {}).get(name, default)

    busy_rises = set()
    for i in range(1, len(trace)):
        if out(trace[i - 1], 'busy') == 0 and out(trace[i], 'busy') == 1:
            busy_rises.add(i)

    positive = []
    for i in range(1, len(trace)):
        # filtered_sda_low rising means the SDA three-sample majority
        # changed from high to low; filtered_scl_high qualifies SCL high.
        if (out(trace[i - 1], 'filtered_sda_low') == 0 and
                out(trace[i], 'filtered_sda_low') == 1 and
                out(trace[i], 'filtered_scl_high') == 1):
            positive.append(i)

    negative = []
    i = 1
    while i < len(trace):
        # A raw SDA fall while both filtered values still describe an idle,
        # high-SCL bus is a candidate short glitch.
        raw_fall = (trace[i - 1].get('inputs', {}).get('sda_i') == 1 and
                    trace[i].get('inputs', {}).get('sda_i') == 0)
        if (raw_fall and out(trace[i], 'filtered_sda_low') == 0 and
                out(trace[i], 'filtered_scl_high') == 1):
            j = i + 1
            while j < len(trace):
                if out(trace[j], 'filtered_scl_high') == 0:
                    break
                if out(trace[j], 'filtered_sda_low') == 1:
                    break
                raw_rise = (trace[j - 1].get('inputs', {}).get('sda_i') == 0 and
                            trace[j].get('inputs', {}).get('sda_i') == 1)
                if raw_rise:
                    negative.append((i, j))
                    break
                j += 1
            i = max(i + 1, j)
        else:
            i += 1

    failures = []
    for i in positive:
        if not any(k >= i for k in busy_rises):
            failures.append((False, trace[i].get('edge'),
                             'filtered SDA majority changed high-to-low while filtered SCL was high, but busy did not rise'))

    for start, end in negative:
        if any(start <= k <= end for k in busy_rises):
            failures.append((False, trace[start].get('edge'),
                             'a raw SDA glitch returned before the filtered majority changed, but busy rose'))

    if failures:
        return failures[0]
    if positive or negative:
        return (True, None,
                'majority-filtered SDA transition caused busy to rise, and short raw glitches caused no busy rise')
    return (None, None, 'no filtered SDA transition or complete short raw SDA glitch was observed')

def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    def inp(row, name):
        return row.get('inputs', {}).get(name)

    def rises(name):
        result = []
        for i in range(1, len(trace)):
            if out(trace[i - 1], name) == 0 and out(trace[i], name) == 1:
                result.append(i)
        return result

    def input_falls(name):
        result = []
        for i in range(1, len(trace)):
            if inp(trace[i - 1], name) == 1 and inp(trace[i], name) == 0:
                result.append(i)
        return result

    busy_rises = set(rises('busy'))

    # Positive route case: the filtered SDA majority changes high-to-low
    # while the filtered SCL majority remains high.  busy must then rise.
    positive = []
    for i in rises('filtered_sda_low'):
        if (out(trace[i], 'filtered_scl_high') == 1 and
                out(trace[i], 'busy') == 0):
            positive.append(i)

    # Negative route case: a raw SDA pulse occurs while filtered SCL is high,
    # but the filtered SDA majority remains high throughout the pulse.
    negative = []
    for start in input_falls('sda_i'):
        if (out(trace[start], 'filtered_scl_high') != 1 or
                out(trace[start], 'filtered_sda_low') != 0 or
                out(trace[start], 'busy') != 0):
            continue
        end = None
        for j in range(start + 1, len(trace)):
            if inp(trace[j - 1], 'sda_i') == 0 and inp(trace[j], 'sda_i') == 1:
                end = j
                break
        if end is None:
            continue
        if all(out(trace[j], 'filtered_sda_low') == 0
               for j in range(start, end + 1)):
            negative.append((start, end))

    if positive and negative:
        for i in positive:
            if not any(j >= i for j in busy_rises):
                return (False, trace[i]['edge'],
                        'filtered SDA majority fell while filtered SCL was high, but busy did not rise')
        for start, end in negative:
            if any(start <= j <= end for j in busy_rises):
                return (False, trace[start]['edge'],
                        'a short SDA glitch left the filtered SDA majority high but busy rose')
        return (True, None,
                'both majority-filtered START evidence and short-glitch rejection were observed through busy')

    return (None, None,
            'the trace showed only one or neither of the two routed majority-filtering cases')

