    sda_changes = edges(trace, "sda_i", "change")
    busy_rises = edges(trace, "busy", "rise")

    def out(row, name, default=0):
        return row.get("outputs", {}).get(name, default)

    def is_idle_high_scl_glitch_start(row):
        return (
            row.get("edge") in sda_changes
            and out(row, "in_idle") == 1
            and out(row, "filtered_scl_high") == 1
            and out(row, "busy") == 0
        )

