    # REQ-0066 itself; it is not asserted here.
    ordinary_start_seen = any(
        row.get("edge") in busy_rises
        and out(row, "start_condition") == 1
        for row in trace
    )

    verdicts = []
    for row in trace:
        start_edge = row.get("edge")
        if not is_idle_high_scl_glitch_start(row):
            continue

        later_changes = {e for e in sda_changes if e != start_edge}
        window = after(
            trace,
            lambda r, e=start_edge: r.get("edge") == e
            and is_idle_high_scl_glitch_start(r),
            until=lambda r, changes=later_changes: r.get("edge") in changes,
        )
        verdicts.append(
            throughout(
                window[0],
                lambda r: out(r, "busy") == 0,
                after_activation=False,
            )
        )

    result = worst(verdicts)
    if result[0] is False:
        return result
    if result[0] is True and not ordinary_start_seen:
        return (None, None, "short SDA glitch was observed, but no contrasting filtered START/busy response was present")
    if result[0] is None:
        return result
    return (True, result[1], "busy remained low during the short SDA pulse; no filtered START was produced")

