        previous = None
        for i, row in enumerate(trace):
            value = inp(row, port)
            if previous is not None and value != previous:
                changes.append((i, previous, value))
            previous = value

        pairs = []
        for first, second in zip(changes, changes[1:]):
            i, old_value, new_value = first
            j, returned_from, returned_to = second
            if returned_from == new_value and returned_to == old_value:
                pairs.append((i, j))
        return pairs

    verdicts = []

    # Observation route through REQ-0066.  The raw SDA pulse is the
    # short-glitch situation; idle and filtered-high qualify that situation.
    # Keep the window open until the controller leaves idle, so a delayed
    # busy response is still checked without imposing a cycle count.
    for first, last in pulse_pairs("sda_i"):
        opening = trace[first]
        if not (
            sig(opening, "in_idle", 0) == 1
            and sig(opening, "filtered_scl_high", 0) == 1
            and sig(opening, "busy", 0) == 0
        ):
            continue

        opening_edge = opening.get("edge")
        windows = after(
            trace,
            lambda r, e=opening_edge: r.get("edge") == e,
            until=lambda r: sig(r, "in_idle", 0) == 0,
        )
        verdicts.extend(
            throughout(w, lambda r: sig(r, "busy", 0) == 0,
                       after_activation=False)
            for w in windows
        )

    # Observation route through REQ-0034.  During READ, initialize dout
    # opposite to the stable filtered SDA value as specified by the route.
    # A short SCL pulse must not change dout; keep checking until READ ends
    # rather than assuming a response latency or filter cycle count.
    for first, last in pulse_pairs("scl_i"):
        opening = trace[first]
        if sig(opening, "in_read_sequence", 0) != 1:
            continue

        filtered_sda_low = sig(opening, "filtered_sda_low", None)
        current_dout = sig(opening, "dout", None)
        if filtered_sda_low not in (0, 1) or current_dout not in (0, 1):
            continue

        stable_sda = 0 if filtered_sda_low else 1
        if current_dout == stable_sda:
            continue

        opening_edge = opening.get("edge")
        windows = after(
            trace,
            lambda r, e=opening_edge: r.get("edge") == e,
            until=lambda r: sig(r, "in_read_sequence", 0) == 0,
        )
        verdicts.extend(
            stable(w, "dout", after_activation=False)
            for w in windows
        )

    result = worst(verdicts)
    if result[0] is None:
        return (None, None, "no qualifying short glitch situation was completed in this trace")
    return result

