def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, eventually, throughout, worst

    def holds(cond):
        def predicate(row):
            for port, value in cond.items():
                if port in row['outputs']:
                    actual = row['outputs'][port]
                else:
                    actual = row['inputs'].get(port)
                if actual != value:
                    return False
            return True
        return predicate

    def any_condition(alternatives):
        predicates = [holds(condition) for condition in alternatives]
        return lambda row: any(predicate(row) for predicate in predicates)

    reset = any_condition([
        {'nReset': 0},
        {'rst': 1},
    ])

    start = lambda row: (
        holds({'scl_i': 1, 'sda_i': 0})(row)
        and row['outputs'].get('start_condition') == 1
    )
    stop = holds({'stop_condition': 1})

    start_windows = after(
        trace,
        start,
        until=stop,
        aborts=reset,
    )

    if not start_windows:
        return (None, None, 'filtered START condition never occurred')

    verdicts = [
        throughout(
            window,
            lambda row: row['outputs'].get('busy') == 1,
            after_activation=True,
        )
        for window in start_windows
    ]

    stop_windows = after(
        trace,
        stop,
        until=TO_END,
        aborts=reset,
    )
    start_edges = [window.edge for window in start_windows]
    relevant_stops = [
        window for window in stop_windows
        if any(window.edge > start_edge for start_edge in start_edges)
    ]

    verdicts.extend(
        eventually(
            window,
            lambda row: row['outputs'].get('busy') == 0,
            strong=True,
            after_activation=True,
        )
        for window in relevant_stops
    )

    return worst(verdicts)

