        'in_read_sequence',
        'in_write_sequence',
    )

    def value(row, port):
        return row.get('outputs', {}).get(port,
               row.get('inputs', {}).get(port))

    def phase(row):
        return tuple(value(row, p) for p in phase_ports)

    def reset_active(row):
        return value(row, 'nReset') == 0 or value(row, 'rst') == 1

    def arbitration_abort(previous, current):
        return (value(current, 'al') == 1 or
                (previous is not None and
                 value(previous, 'al') == 0 and value(current, 'al') == 1))

    witnessed = False
    previous = None

    for row in trace:
        if previous is None:
            previous = row
            continue

        if reset_active(previous) or reset_active(row):
            previous = row
            continue

        if arbitration_abort(previous, row):
            previous = row
            continue

        phase_changed = phase(previous) != phase(row)
        scl_phase_changed = value(previous, 'scl_oen') != value(row, 'scl_oen')
        active = any(value(previous, p) == 1 or value(row, p) == 1
                     for p in phase_ports)

        if active and (phase_changed or scl_phase_changed):
            witnessed = True
            if value(row, 'clk_en_asserted') != 1:
