def decide(trace):
    from specflow.refmodel.temporal import after, edges, eventually, worst

    def any_condition(conditions):
        def predicate(row):
            return any(
                all(row['outputs'].get(port, row['inputs'].get(port)) == value
                    for port, value in condition.items())
                for condition in conditions
            )
        return predicate

    active_rises = edges(trace, 'fsm_active', 'rise')
    applies = lambda row: (
        row['edge'] in active_rises
        and row['inputs'].get('ena') == 1
        and row['outputs'].get('fsm_active') == 1
        and row['outputs'].get('in_idle') != 1
    )
    aborts = any_condition([
        {'al': 1},
        {'nReset': 0},
        {'rst': 1},
    ])

    windows = after(
        trace,
        applies,
        until=lambda row: row['outputs'].get('cmd_ack') == 1,
        aborts=aborts,
    )

    verdicts = []
    for window in windows:
        completion = eventually(
            window,
            lambda row: (
                row['outputs'].get('cmd_ack') == 1
                and row['outputs'].get('in_idle') == 1
            ),
            strong=True,
            after_activation=True,
        )
        if completion[0] is False or completion[0] is None:
            verdicts.append(completion)
            continue

        ack_rows = [
            row for row in window.rows
            if row['outputs'].get('cmd_ack') == 1
        ]
        if not ack_rows:
            verdicts.append((None, window.edge, 'cmd_ack completion evidence was not observable'))
            continue

        ack = ack_rows[0]
        ack_pos = next(
            (i for i, row in enumerate(trace) if row.get('index') == ack.get('index')),
            None,
        )
        if ack_pos is None:
            verdicts.append((None, ack.get('edge'), 'cmd_ack pulse position was not observable'))
            continue

        duration = 0
        i = ack_pos
        while i < len(trace) and trace[i]['outputs'].get('cmd_ack') == 1:
            duration += trace[i].get('held', 1)
            i += 1

        if i == len(trace):
            verdicts.append((None, ack.get('edge'), 'cmd_ack remained high at the end of the trace; pulse termination was not observed'))
        elif duration != 1:
            verdicts.append((False, ack.get('edge'), f'cmd_ack was high for {duration} clock edge(s), expected exactly one'))
        else:
            verdicts.append((True, ack.get('edge'), 'FSM was idle and cmd_ack was high for exactly one clock cycle'))

    return worst(verdicts)

