def decide(trace):
    def outputs(row):
        return row.get('outputs', {})

    def reset_active(row):
        ins = row.get('inputs', {})
        return ins.get('nReset') == 0 or ins.get('rst') == 1

    def changed_into(i, port, value):
        if i <= 0:
            return False
        return outputs(trace[i]).get(port) == value and outputs(trace[i - 1]).get(port) != value

    activations = []
    for i in range(1, len(trace)):
        before = outputs(trace[i - 1]).get('in_start_sequence')
        now = outputs(trace[i]).get('in_start_sequence')
        if before != 1 and now == 1:
            activations.append(i)

    if not activations:
        return (None, None, 'in_start_sequence never rose; no START sequence occurred')

    for start in activations:
        end = len(trace)
        aborted = None
        for i in range(start, len(trace)):
            if reset_active(trace[i]):
                aborted = i
                end = i
                break

        released_i = None
        sda_pull_i = None
        for i in range(start, end):
            o = outputs(trace[i])
            if o.get('sda_oen') == 1 and o.get('scl_oen') == 1:
                released_i = i
            if (
                released_i is not None
                and i > released_i
                and changed_into(i, 'sda_oen', 0)
                and o.get('scl_oen') == 1
            ):
                sda_pull_i = i
                break

        if sda_pull_i is None:
            if aborted is not None:
                continue
            return (False, trace[start].get('edge'),
                    'START sequence did not pull SDA low after the released SDA/SCL state')

        scl_pull_i = None
        for i in range(sda_pull_i + 1, end):
            o = outputs(trace[i])
            if changed_into(i, 'scl_oen', 0) and o.get('sda_oen') == 0:
                scl_pull_i = i
                break

        if scl_pull_i is None:
            if aborted is not None:
                continue
            return (False, trace[sda_pull_i].get('edge'),
                    'START sequence pulled SDA low but did not subsequently pull SCL low')

        ack_i = None
        for i in range(scl_pull_i, end):
            if outputs(trace[i]).get('cmd_ack') == 1 and changed_into(i, 'cmd_ack', 1):
                ack_i = i
                break

        if ack_i is None:
            if aborted is not None:
                continue
            return (False, trace[scl_pull_i].get('edge'),
                    'START sequence pulled SCL low but cmd_ack did not assert')

