from specflow.refmodel.temporal import TO_END, after, edges


def decide(trace):
    def inp(row, name, value):
        return row['inputs'].get(name) == value

    def out(row, name, value):
        return row['outputs'].get(name) == value

    def normal(row):
        return inp(row, 'nReset', 1) and inp(row, 'rst', 0)

    def aborted(row):
        return inp(row, 'nReset', 0) or inp(row, 'rst', 1)

    reset_windows = after(trace, normal, until=TO_END, aborts=aborted)
    if not reset_windows:
        return (None, None, 'reset never completed; continuous sampling was not exercised')

    active_rows = reset_windows[0].rows
    if not active_rows:
        return (None, reset_windows[0].edge, 'reset completed but no post-reset state was observed')

    busy_rises = edges(trace, 'busy', 'rise')

    start_windows = after(
        trace,
        lambda r: normal(r) and out(r, 'start_condition', 1) and out(r, 'busy', 0),
        until=TO_END,
        aborts=aborted,
    )

    if not start_windows:
        return (None, None, 'no sampled START condition occurred after reset')

    for window in start_windows:
        rows = window.rows
        start_edge = window.edge
        saw_stop = False
        found_busy_rise = False
        for row in rows:
            if aborted(row):
                break
            if out(row, 'stop_condition', 1):
                saw_stop = True
                break
            if row['edge'] in busy_rises:
                found_busy_rise = True
                break
        if saw_stop or not found_busy_rise:
            return (
                False,
                start_edge,
                'a sampled START occurred after reset but busy did not rise before the transaction ended',
            )

    non_start_evidence = False
    for i, row in enumerate(active_rows):
        if aborted(row):
            break
        is_start = out(row, 'start_condition', 1)
        if not is_start:
            non_start_evidence = True
        if row['edge'] not in busy_rises:
            continue
        if is_start:
            continue
        j = i - 1
        while j >= 0 and out(active_rows[j], 'busy', 1):
            j -= 1
        pending_start = any(
            out(active_rows[k], 'start_condition', 1)
            for k in range(max(0, j + 1), i + 1)
        )
        if not pending_start:
            return (
                False,
                row['edge'],
                'busy rose after reset without a sampled START condition',
            )

    if not non_start_evidence:
        return (None, None, 'the trace showed sampled START activity but no no-START case')

    return (
        True,
        None,
        'post-reset sampled START conditions produced busy rises, and busy stayed unchanged without a pending sampled START',
    )

