    start_rises = edges(trace, 'start_condition', 'rise')
    busy_rises = edges(trace, 'busy', 'rise')
    saw_start_case = False
    saw_no_start_case = False

    for window in windows:
        rows = window.rows
        if not rows:
            continue

        start_edges = [
            r['edge'] for r in rows
            if r['edge'] in start_rises and value(r, 'busy') == 0
        ]
        if start_edges:
            saw_start_case = True
            for start_edge in start_edges:
                later_busy = [e for e in busy_rises if e > start_edge]
                if later_busy:
                    continue
                if any(reset_active(r) for r in rows):
                    return (None, start_edge, 'the sampling attempt was aborted by reset before busy could respond')
                return (False, start_edge, 'a valid sampled START occurred after reset, but busy did not rise')

        busy_rise_rows = [r for r in rows if r['edge'] in busy_rises]
        for row in busy_rise_rows:
            prior_starts = [e for e in start_rises if e < row['edge'] and e >= window.edge]
            if prior_starts:
                continue
            saw_no_start_case = True
            return (False, row['edge'], 'busy rose after reset without a preceding sampled START condition')

        if not start_edges:
            saw_no_start_case = True

    if not saw_start_case or not saw_no_start_case:
        return (None, None, 'post-reset idle operation did not exercise both sampled-START and no-START routed observations')

    return (True, None, 'after reset, sampled START activity produced a busy rise and busy remained unchanged without a sampled START')

from specflow.refmodel.temporal import TO_END, after, edges, eventually, worst


def decide(trace):
