            row.get('edge') in start_rises
            and out(row, 'filtered_scl_high') == 1
            and not reset_active(row)
        ),
        until=TO_END,
        aborts=reset_active,
    )

    if not windows:
        return (None, None, 'no post-reset filtered START with filtered SCL high occurred; continuous sampling was not exercised')

    busy_rises = edges(trace, 'busy', 'rise')
    verdicts = [
        eventually(
            window,
            lambda row: row.get('edge') in busy_rises,
            strong=True,
            after_activation=False,
        )
        for window in windows
    ]
    return worst(verdicts)

