def decide(trace):
    def reset(row):
        return row['inputs'].get('nReset') == 0 or row['inputs'].get('rst') == 1

    def inp(row, name):
        return row['inputs'].get(name)

    def out(row, name):
        return row['outputs'].get(name)

    activations = []
    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        if reset(row) or reset(prev):
            continue
        if inp(row, 'scl_i') != 1:
            continue
        old_sda = inp(prev, 'sda_i')
        new_sda = inp(row, 'sda_i')
        if old_sda == 1 and new_sda == 0:
            activations.append((i, 1, 'raw SDA high-to-low transition'))
        elif old_sda == 0 and new_sda == 1:
            activations.append((i, 0, 'raw SDA low-to-high transition'))

    if not activations:
        return (None, None, 'no raw SDA transition while raw SCL was high')

    saw_evidence = False
    for start, expected_busy, transition_text in activations:
        initial_sda = inp(trace[start], 'sda_i')
        for j in range(start + 1, len(trace)):
            row = trace[j]
            if reset(row):
                break

            # The stable raw transition has ended; this occurrence is no
            # longer the situation described by the routed observation.
            if inp(row, 'sda_i') != initial_sda:
                break

            previous_busy = out(trace[j - 1], 'busy')
            current_busy = out(row, 'busy')
            if current_busy != previous_busy:
                if current_busy != expected_busy:
                    return (False, row.get('edge'),
                            f'{transition_text} was followed by busy changing to {current_busy}, '
                            f'but the routed observation requires busy to change to {expected_busy}')
                saw_evidence = True
                break

    if saw_evidence:
        return (True, None,
                'raw SDA transition was followed by the corresponding routed busy transition '
                'after synchronization and filtering')
    return (None, None,
            'raw SDA transition occurred, but the trace ended or the transition was withdrawn '
            'before routed synchronized busy evidence appeared')

def decide(trace):
    seen_captured = False
    seen_brief = False

    def reset(row):
        return row['inputs'].get('nReset') == 0 or row['inputs'].get('rst') == 1

    for i in range(1, len(trace)):
        before = trace[i - 1]
        row = trace[i]
        if reset(before) or reset(row):
            continue

        scl = row['inputs'].get('scl_i')
        prev_sda = before['inputs'].get('sda_i')
        sda = row['inputs'].get('sda_i')
        if scl != 1 or sda == prev_sda:
            continue

        if sda == 0 and prev_sda == 1:
            expected_busy = 1
        elif sda == 1 and prev_sda == 0:
            expected_busy = 0
        else:
            continue

        prior_busy = before['outputs'].get('busy')
        if prior_busy == expected_busy:
            continue

        outcome = None
        for j in range(i + 1, len(trace)):
            current = trace[j]
            if reset(current):
                outcome = 'aborted'
                break

            busy = current['outputs'].get('busy')
            if busy != prior_busy:
                if busy == expected_busy:
                    outcome = 'captured'
                else:
                    return (False, current.get('edge'),
                            'busy changed to the wrong value after the raw SDA transition; '
                            'the transition was not correctly reflected after synchronization and filtering')
                break

            current_sda = current['inputs'].get('sda_i')
            previous_sda = trace[j - 1]['inputs'].get('sda_i')
            reversed_transition = (
                current['inputs'].get('scl_i') == 1 and
                current_sda != previous_sda and
                current_sda == prev_sda
            )
            if reversed_transition:
                outcome = 'brief'
                break

        if outcome == 'captured':
            seen_captured = True
        elif outcome == 'brief':
            if trace[j]['outputs'].get('busy') != prior_busy:
                return (False, trace[j].get('edge'),
                        'busy changed for a raw SDA transition that reversed before synchronization and filtering could capture it')
            seen_brief = True
        elif outcome == 'aborted':
            continue
        else:
            return (None, row.get('edge'),
                    'raw SDA transition occurred, but the trace ended before synchronization/filter response or reversal was observable')

    if not seen_captured and not seen_brief:
        return (None, None, 'no licensed raw SDA transition case was observed')
    if not (seen_captured and seen_brief):
        return (None, None,
                'only one routed busy case was observed; both captured and too-brief transition behavior are needed to decide this route')
    return (True, None,
            'busy reflected a persistent raw SDA transition and remained unchanged for a transition too brief to be captured')

