def decide(trace):
    evidence_edge = None

    def reset_active(row):
        inputs = row.get('inputs', {})
        return inputs.get('nReset') == 0 or inputs.get('rst') == 1

    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]

        if reset_active(prev) or reset_active(row):
            continue

        previous_inputs = prev.get('inputs', {})
        current_inputs = row.get('inputs', {})
        sda_changed = (current_inputs.get('sda_i') !=
                       previous_inputs.get('sda_i'))
        scl_high = current_inputs.get('scl_i') == 1
        if not (sda_changed and scl_high):
            continue

        previous_busy = prev.get('outputs', {}).get('busy')
        current_busy = row.get('outputs', {}).get('busy')

        if current_busy != previous_busy:
            return (False, row.get('edge'),
                    'busy changed with the raw START/STOP-capable bus transition, before the two-stage capture path could be used')

        for j in range(i + 1, len(trace)):
            candidate = trace[j]
            if reset_active(candidate):
                break
            before = trace[j - 1].get('outputs', {}).get('busy')
            after = candidate.get('outputs', {}).get('busy')
            if after != before:
                evidence_edge = candidate.get('edge')
                break

        if evidence_edge is not None:
            break

    if evidence_edge is None:
        return (None, None,
                'busy did not provide the later synchronized START/STOP signature; the routed situation was not fully observed')

    return (True, evidence_edge,
            'busy remained unchanged at the raw bus transition and changed only at a later state after synchronized capture and detection')

def decide(trace):
    activations = []

    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        prev_sda = prev['inputs'].get('sda_i')
        sda = row['inputs'].get('sda_i')
        scl = row['inputs'].get('scl_i')
        if prev_sda is None or sda is None or scl != 1:
            continue
        if sda != prev_sda:
            activations.append(i)

    if not activations:
        return (None, None,
                'no raw sda_i transition while scl_i was high; no possible START/STOP capture situation occurred')

    observed = []
    for i in activations:
        prior_busy = trace[i - 1]['outputs'].get('busy')
        current_busy = trace[i]['outputs'].get('busy')
        if prior_busy is None or current_busy is None:
            continue

        if current_busy != prior_busy:
            return (False, trace[i].get('edge'),
                    'busy changed on the same distinct state as the raw bus transition; '
                    'the controller used the raw input before synchronized capture')

        for j in range(i + 1, len(trace)):
            if trace[j]['outputs'].get('busy') != prior_busy:
                observed.append(
                    (True, trace[j].get('edge'),
                     'busy remained at its prior value on the raw transition state and changed only later, '
                     'after the captured bus condition propagated to the controller')
                )
                break

    if observed:
        return observed[0]

    return (None, None,
            'the raw transition was observed without premature busy use, but no later routed busy change '
            'provided evidence of controller use in this trace')

def decide(trace):
    def reset_active(row):
        ins = row.get('inputs', {})
        return ins.get('nReset') == 0 or ins.get('rst') == 1

    def outputs(row):
        return row.get('outputs', {})

    saw_routed_response = False

    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        if reset_active(prev) or reset_active(row):
            continue

        prev_in = prev.get('inputs', {})
        cur_in = row.get('inputs', {})
        if cur_in.get('scl_i') != 1:
            continue
        if cur_in.get('sda_i') == prev_in.get('sda_i'):
            continue

        baseline_busy = outputs(prev).get('busy')
        elapsed = 0
        detection_seen = False

        for j in range(i, len(trace)):
            current = trace[j]
            if reset_active(current):
                break

            if j > i:
                elapsed += trace[j - 1].get('held', 1)

            out = outputs(current)
            if out.get('start_condition') == 1 or out.get('stop_condition') == 1:
                detection_seen = True

            busy = out.get('busy')
            if busy != baseline_busy:
                if elapsed < 2:
                    return (
                        False,
                        current.get('edge'),
                        'busy changed during the first two rising edges after a raw START/STOP-capable transition; the captured bus signals were used before the two-stage capture latency elapsed'
                    )
                if not detection_seen:
                    return (
                        False,
                        current.get('edge'),
                        'busy changed after the raw bus transition without a prior declared synchronized START/STOP detection condition'
                    )
                saw_routed_response = True
                break

        if saw_routed_response:
            return (
                True,
                None,
                'busy remained unchanged through the two rising-edge capture latency and changed only after the declared synchronized/filter detection path'
            )

    if not saw_routed_response:
        return (
            None,
            None,
            'no busy response was observed after a raw START/STOP-capable scl_i/sda_i transition; this trace does not expose a violation of the two-stage capture requirement'
        )

