def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, eventually, worst

    def activation(row):
        out = row['outputs']
        return (row['inputs'].get('ena') == 1 and
                (out.get('start_condition') == 1 or
                 out.get('stop_condition') == 1))

    windows = after(trace, activation, until=TO_END)
    if not windows:
        return (None, None, 'no filtered START or STOP condition occurred')

    verdicts = []
    for window in windows:
        opened = window.rows[0]['outputs']
        if opened.get('start_condition') == 1:
            expected = 1
            condition = 'filtered START'
        else:
            expected = 0
            condition = 'filtered STOP'

        verdicts.append(
            eventually(
                window,
                lambda row, expected=expected: row['outputs'].get('busy') == expected,
                after_activation=True,
                strong=False))

    return worst(verdicts)

def decide(trace):
    def out(row, name, default=0):
        return row.get('outputs', {}).get(name, default)

    # The normalized activation is the filtering stage operating while enabled.
    filtering_seen = any(
        row.get('inputs', {}).get('ena') == 1 and
        out(row, 'filter_sample_tick') == 1
        for row in trace
    )
    if not filtering_seen:
        return (None, None, 'the filtering-stage activation never occurred')

    accepted = []
    for i, row in enumerate(trace):
        if out(row, 'start_condition') == 1:
            accepted.append((i, 1, 'filtered START'))
        if out(row, 'stop_condition') == 1:
            accepted.append((i, 0, 'filtered STOP'))

    checked = False
    for i, target, label in accepted:
        checked = True
        busy_at_activation = out(trace[i], 'busy')
        if busy_at_activation == target:
            continue
        found = False
        for j in range(i + 1, len(trace)):
            busy = out(trace[j], 'busy')
            if busy != busy_at_activation:
                if busy == target:
                    found = True
                    break
                return (False, trace[j].get('edge'),
                        f'{label} was accepted by the filtering stage but busy changed to {busy}, not {target}')
        if not found:
            return (None, None,
                    f'{label} was accepted, but the trace ended before the filtered busy response was observable')

    # A raw SDA transition which returns without producing a filtered START or
    # STOP is the route's negative case: filtering must suppress it at busy.
    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        if (prev.get('inputs', {}).get('ena') != 1 or
                row.get('inputs', {}).get('ena') != 1 or
                prev.get('inputs', {}).get('sda_i') == row.get('inputs', {}).get('sda_i') or
                out(row, 'filtered_scl_high') != 1):
            continue

        original = prev.get('inputs', {}).get('sda_i')
        for j in range(i + 1, len(trace)):
            if out(trace[j], 'start_condition') == 1 or out(trace[j], 'stop_condition') == 1:
                break
            if trace[j].get('inputs', {}).get('sda_i') == original:
                before = out(prev, 'busy')
                if any(out(trace[k], 'busy') != before for k in range(i, j + 1)):
                    return (False, trace[i].get('edge'),
                            'an SDA transition rejected by the digital filter changed busy')
                checked = True
                break

    if not checked:
        return (None, None, 'no accepted or rejected bus transition was observable')
    return (True, None, 'filtered bus transitions were distinguished from an unaccepted SDA transition')

def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    accepted = []
    for i, row in enumerate(trace):
        if out(row, 'start_condition') == 1:
            accepted.append((i, 1, 'filtered START'))
        if out(row, 'stop_condition') == 1:
            accepted.append((i, 0, 'filtered STOP'))

    # The routed busy signature must reflect an accepted filtered condition.
    for i, expected, name in accepted:
        before = out(trace[i - 1], 'busy') if i > 0 else None
        for j in range(i, len(trace)):
            value = out(trace[j], 'busy')
            if value == expected:
                if before is not None and before != expected:
                    return (True, trace[j].get('edge'),
                            f'{name} was reflected by busy after filtering')
                # The state is already correct; the trace does not prove a
                # transition, but it does show the routed filtered state.
                return (True, trace[j].get('edge'),
                        f'{name} produced the expected busy state')
            if value is not None and value != before and before is not None:
                return (False, trace[j].get('edge'),
                        f'{name} produced busy={value}, expected {expected} after filtering')
        return (None, None, f'{name} was detected but the filtered busy response was not observed')

    # A raw SDA transition that reverses before either filtered condition is
    # detected is the routed negative signature of input filtering.
    raw_changes = []
