                trace[i - 1].get('inputs', {}).get('sda_i')):
            if out(trace[i], 'filtered_scl_high') == 1:
                raw_changes.append(i)

    for pos, i in enumerate(raw_changes):
        end = raw_changes[pos + 1] if pos + 1 < len(raw_changes) else None
        if end is None:
            continue
        if any(i <= k <= end and
               (out(trace[k], 'start_condition') == 1 or
                out(trace[k], 'stop_condition') == 1)
               for k in range(i, end + 1)):
            continue
        initial = out(trace[i - 1], 'busy')
        if initial is None:
            continue
        for k in range(i, end + 1):
            if out(trace[k], 'busy') != initial:
                return (False, trace[k].get('edge'),
                        'an SDA transition not accepted by the digital filter changed busy')
        return (True, trace[end].get('edge'),
                'an unaccepted SDA transition left busy unchanged through the filter interval')

    return (None, None, 'no filtered condition or sufficiently exercised unaccepted SDA transition occurred')

