def decide(trace):
    def inp(row, name):
        return row.get('inputs', {}).get(name)

    def sig(row, name):
        return row.get('outputs', {}).get(name)

    if len(trace) < 2:
        return (None, None, 'no complete reset-and-transition transaction is visible')

    trigger = None
    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        if (inp(prev, 'nReset') == 1 and inp(prev, 'rst') == 0 and
                inp(row, 'nReset') == 1 and inp(row, 'rst') == 0 and
                inp(row, 'ena') == 1 and inp(row, 'scl_i') == 1 and
                inp(prev, 'sda_i') == 1 and inp(row, 'sda_i') == 0 and
                sig(prev, 'filtered_sda_low') == 0 and
                sig(prev, 'filtered_scl_high') == 1):
            trigger = i
            break

    if trigger is None:
        return (None, None, 'no post-reset stable SDA high-to-low transition with SCL high occurred')

    clk_cnt = inp(trace[trigger], 'clk_cnt')
    if not isinstance(clk_cnt, int):
        return (None, trace[trigger].get('edge'), 'clk_cnt was not available for the sampling-interval check')
    expected = max(1, clk_cnt >> 2)

    tick_rows = []
    busy_rise = None
    for i in range(trigger, len(trace)):
        row = trace[i]
        if inp(row, 'nReset') != 1 or inp(row, 'rst') != 0 or inp(row, 'ena') != 1:
            return (None, row.get('edge'), 'the enabled post-reset transaction was interrupted')
        if inp(row, 'clk_cnt') != clk_cnt:
            return (None, row.get('edge'), 'clk_cnt changed before the sampling cadence could be decided')
        if sig(row, 'filter_sample_tick') == 1 and (i == trigger or sig(trace[i - 1], 'filter_sample_tick') != 1):
            tick_rows.append(i)
        if i > trigger and sig(trace[i - 1], 'busy') != 1 and sig(row, 'busy') == 1:
            busy_rise = i
            break

    if busy_rise is None:
        return (None, None, 'the resulting filtered START and busy rise were not observed')

    tick_rows = [i for i in tick_rows if i <= busy_rise]
    if len(tick_rows) < 2:
        return (None, trace[busy_rise].get('edge'), 'fewer than two filter samples were visible before busy rose')

    for a, b in zip(tick_rows, tick_rows[1:]):
        enabled_edges = sum(trace[j].get('held', 0) for j in range(a, b))
        if enabled_edges != expected:
            return (False, trace[b].get('edge'),
                    f'filter_sample_tick interval was {enabled_edges} enabled clocks; '
                    f'the clause requires max(1, floor(clk_cnt >> 2)) = {expected}')

    return (True, trace[busy_rise].get('edge'),
            f'filter_sample_tick intervals matched max(1, floor(clk_cnt >> 2)) = {expected} '
            'enabled clocks before the filtered START busy indication')

def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    def enabled_edges(rows):
        return sum(r.get('held', 1) for r in rows if r.get('inputs', {}).get('ena') == 1)

    # Establish a real START-like bus transition, rather than opening on ena
    # alone.  Reset and disabled sampling do not belong to this transaction.
    starts = []
    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        if (prev.get('inputs', {}).get('sda_i') == 1 and
                row.get('inputs', {}).get('sda_i') == 0 and
                row.get('inputs', {}).get('scl_i') == 1 and
                row.get('inputs', {}).get('ena') == 1 and
                row.get('inputs', {}).get('nReset') == 1 and
                row.get('inputs', {}).get('rst') != 1):
            starts.append(i)

    if not starts:
        return (None, None, 'no stable SDA high-to-low transition while SCL was high with ena enabled')

    for start_i in starts:
        busy_i = None
        for j in range(start_i + 1, len(trace)):
            if (out(trace[j], 'busy') == 1 and
                    out(trace[j - 1], 'busy') != 1):
                busy_i = j
                break

        if busy_i is None:
            continue

        ticks = []
        for j in range(start_i, busy_i + 1):
            now = out(trace[j], 'filter_sample_tick')
            before = out(trace[j - 1], 'filter_sample_tick') if j > 0 else 0
            if now == 1 and before != 1:
                ticks.append(j)

        if len(ticks) < 2:
            continue

        for a, b in zip(ticks, ticks[1:]):
            interval = enabled_edges(trace[a:b])
            count = trace[a].get('inputs', {}).get('clk_cnt')
            if not isinstance(count, int):
                return (None, None, 'clk_cnt was unavailable at a filter sample')
            expected = max(1, count >> 2)
            if interval != expected:
                return (False, trace[b].get('edge'),
                        f"filter_sample_tick interval was {interval} enabled clocks, expected max(1, clk_cnt >> 2) = {expected}")

        return (True, trace[busy_i].get('edge'),
                'filter_sample_tick spacing matched the stated clk_cnt >> 2 sampling interval')

    return (None, None, 'the SDA transition did not produce a routed busy detection with enough filter samples to decide the interval')

def decide(trace):
    def inp(row, name):
        return row.get('inputs', {}).get(name)

    def sig(row, name):
        return row.get('outputs', {}).get(name)

    if len(trace) < 2:
        return (None, None, 'the post-reset filtered-START situation was not observed')

    trigger = None
    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        if (inp(prev, 'nReset') == 1 and inp(prev, 'rst') == 0 and
                inp(row, 'nReset') == 1 and inp(row, 'rst') == 0 and
                inp(prev, 'ena') == 1 and inp(row, 'ena') == 1 and
                inp(prev, 'scl_i') == 1 and inp(row, 'scl_i') == 1 and
                inp(prev, 'sda_i') == 1 and inp(row, 'sda_i') == 0 and
                sig(prev, 'in_idle') == 1 and
                sig(prev, 'filtered_scl_high') == 1 and
                sig(prev, 'filtered_sda_low') == 0 and
                sig(prev, 'busy') == 0):
            trigger = i
            break

    if trigger is None:
        return (None, None,
                'no post-reset idle high-SCL SDA high-to-low transition occurred')

    clk_cnt = inp(trace[trigger], 'clk_cnt')
    if not isinstance(clk_cnt, int):
        return (None, trace[trigger].get('edge'),
                'clk_cnt was unavailable for the stated `clk_cnt >> 2` interval')
    expected = max(1, clk_cnt >> 2)

    sample_rows = []
    busy_rise = None
    for i in range(trigger, len(trace)):
        row = trace[i]
        if (inp(row, 'nReset') != 1 or inp(row, 'rst') != 0 or
                inp(row, 'ena') != 1):
            return (None, row.get('edge'),
                    'the enabled post-reset filtered-START situation was interrupted')
        if inp(row, 'clk_cnt') != clk_cnt:
            return (None, row.get('edge'),
                    'clk_cnt changed before the stated sampling cadence was observable')
        if sig(row, 'filtered_scl_high') != 1:
            return (None, row.get('edge'),
                    'filtered SCL stopped being high before the filtered START completed')

        tick = sig(row, 'filter_sample_tick') == 1
        prior_tick = i > trigger and sig(trace[i - 1], 'filter_sample_tick') == 1
        if tick and not prior_tick:
            sample_rows.append(i)

        if i > trigger:
            prior_busy = sig(trace[i - 1], 'busy') == 1
            current_busy = sig(row, 'busy') == 1
            if not prior_busy and current_busy:
                busy_rise = i
                break

    if busy_rise is None:
        return (None, None,
                'the routed busy rise for the resulting filtered START was not observed')

    sample_rows = [i for i in sample_rows if i <= busy_rise]
    if len(sample_rows) < 2:
        return (None, trace[busy_rise].get('edge'),
                'fewer than two filter-sample events were visible before the routed busy rise')

    for a, b in zip(sample_rows, sample_rows[1:]):
        enabled_edges = sum(trace[j].get('held', 0) for j in range(a, b))
        if enabled_edges != expected:
            return (False, trace[b].get('edge'),
                    f'filter-sample interval was {enabled_edges} enabled clocks; '
                    f'the clause requires max(1, floor(clk_cnt >> 2)) = {expected}')

    return (True, trace[busy_rise].get('edge'),
            f'filter-sample intervals matched max(1, floor(clk_cnt >> 2)) = {expected} '
            'enabled clocks through the filtered START observation')

