def decide(trace):
    from specflow.refmodel.temporal import edges

    tick_edges = edges(trace, "filter_sample_tick", "rise")
    observations = []

    for i, row in enumerate(trace):
        if row["edge"] not in tick_edges:
            continue
        if row["inputs"].get("ena") != 1:
            continue
        if row["outputs"].get("filtered_scl_high") != 1:
            continue
        if i == 0:
            continue

        prev = trace[i - 1]
        old_sda_low = prev["outputs"].get("filtered_sda_low")
        new_sda_low = row["outputs"].get("filtered_sda_low")
        old_busy = prev["outputs"].get("busy")
        new_busy = row["outputs"].get("busy")

        if old_sda_low is None or new_sda_low is None or old_busy is None or new_busy is None:
            continue

        sda_transition = old_sda_low != new_sda_low
        observations.append((row, sda_transition, old_sda_low, new_sda_low,
                             old_busy, new_busy))

    if not observations:
        return (None, None, "no enabled filter-sample update occurred while filtered SCL was high")

    saw_transition = any(item[1] for item in observations)
    saw_no_transition = any(not item[1] for item in observations)

    for row, transitioned, old_sda_low, new_sda_low, old_busy, new_busy in observations:
        if transitioned:
            expected_busy = 1 if new_sda_low == 1 else 0
        else:
            expected_busy = old_busy

        if new_busy != expected_busy:
            if transitioned:
                direction = "high-to-low" if new_sda_low == 1 else "low-to-high"
                return (False, row["edge"],
                        f"busy was {new_busy}, expected {expected_busy} for filtered SDA {direction} transition")
            return (False, row["edge"],
                    f"busy changed from {old_busy} to {new_busy} when the filter sample did not change filtered SDA")

    if not (saw_transition and saw_no_transition):
        return (None, observations[0][0]["edge"],
                "only one side of the routed majority-filter difference was exercised")

    return (True, None,
            "busy matched both majority-filtered SDA transitions and non-transition sample updates")

def decide(trace):
    from specflow.refmodel.temporal import edges

    tick_rises = edges(trace, "filter_sample_tick", "rise")
    sda_changes = edges(trace, "sda_i", "change")
    observed = False

    for i in range(1, len(trace)):
        row = trace[i]
        prev = trace[i - 1]
        inp = row.get("inputs", {})
        out = row.get("outputs", {})
        prev_out = prev.get("outputs", {})

        if inp.get("ena") != 1 or inp.get("nReset") == 0 or inp.get("rst") == 1:
            continue
        if out.get("busy") == prev_out.get("busy"):
            continue

        # A busy transition is the routed observable of a majority-filtered
        # SDA transition.  It must occur at an enabled filter update while
        # filtered SCL is high.
        if row.get("edge") not in tick_rises or out.get("filtered_scl_high") != 1:
            return (False, row.get("edge"),
                    "busy changed outside an enabled filter sample while filtered SCL was high")

        prior_sda_change = any(e <= row.get("edge") for e in sda_changes)
        if not prior_sda_change:
            continue

        observed = True
        sda = inp.get("sda_i")
        expected_busy = 1 if sda == 0 else 0
        if out.get("busy") != expected_busy:
            return (False, row.get("edge"),
                    "busy direction disagrees with the observed SDA transition at the majority-filter update")

    if not observed:
        return (None, None,
                "no attributable majority-filtered SDA transition was observable through busy")
    return (True, None,
            "all observable busy transitions followed enabled majority-filter updates with filtered SCL high")

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, worst

    def applies(row):
        outputs = row.get("outputs", {})
        inputs = row.get("inputs", {})
        return (
            inputs.get("ena") == 1
            and outputs.get("filter_sample_tick") == 1
            and outputs.get("filtered_scl_high") == 1
        )

    windows = after(trace, applies, overlap=True, until=TO_END)
    verdicts = []
    saw_transition_case = False
    saw_no_transition_case = False

    for window in windows:
        if not window.rows:
            continue
        row = window.rows[0]
        i = row["index"]
        if i <= 0:
            continue

        previous = trace[i - 1]
        previous_outputs = previous.get("outputs", {})
        outputs = row.get("outputs", {})

        old_sda = previous_outputs.get("filtered_sda_low")
        new_sda = outputs.get("filtered_sda_low")
        old_busy = previous_outputs.get("busy")
        new_busy = outputs.get("busy")
        if None in (old_sda, new_sda, old_busy, new_busy):
            continue

        sda_changed = old_sda != new_sda
        busy_changed = old_busy != new_busy

        if sda_changed:
            saw_transition_case = True
            expected_busy = 1 if new_sda == 1 else 0
            direction = "high-to-low" if new_sda == 1 else "low-to-high"
            if not busy_changed or new_busy != expected_busy:
                verdicts.append((
                    False,
                    row["edge"],
                    f"busy did not change to {expected_busy} for majority-filtered SDA {direction} transition"
                ))
            else:
                verdicts.append((
                    True,
                    row["edge"],
                    f"busy changed to {expected_busy} for majority-filtered SDA {direction} transition"
                ))
        else:
            saw_no_transition_case = True
            if busy_changed:
                verdicts.append((
                    False,
                    row["edge"],
                    f"busy changed from {old_busy} to {new_busy} although the majority-filtered SDA value did not transition"
                ))
            else:
                verdicts.append((
                    True,
                    row["edge"],
                    "busy remained unchanged while the majority-filtered SDA value did not transition"
                ))

    if not verdicts:
        return (None, None, "no enabled filter-sample update while filtered SCL was high")

    result = worst(verdicts)
    if result[0] is False:
        return result
    if not (saw_transition_case and saw_no_transition_case):
        return (None, result[1], "only one side of the routed majority-filter difference was exercised")
    return (True, result[1], "busy showed the required transition and non-transition majority-filter behavior")

def decide(trace):
    events = []
    for i in range(1, len(trace)):
        row = trace[i]
        prev = trace[i - 1]
        outputs = row.get('outputs', {})
        prev_outputs = prev.get('outputs', {})
        if (row.get('inputs', {}).get('ena') == 1
                and outputs.get('filter_sample_tick') == 1
                and outputs.get('filtered_scl_high') == 1
                and outputs.get('filtered_sda_low') != prev_outputs.get('filtered_sda_low')):
            events.append((row, outputs.get('filtered_sda_low')))

    if not events:
        return (None, None, 'no enabled filter-sample transition of filtered SDA while filtered SCL was high')

    for row, filtered_low in events:
        expected_busy = 1 if filtered_low == 1 else 0
        if row.get('outputs', {}).get('busy') != expected_busy:
            direction = 'high-to-low' if expected_busy else 'low-to-high'
            return (False, row.get('edge'),
                    f'busy was not {expected_busy} for the majority-filtered SDA {direction} transition')

    return (True, events[-1][0].get('edge'),
            f'{len(events)} enabled majority-filtered SDA transition(s) were reflected on busy')

