            actual = outputs.get('dout')
            if actual != previous_dout and not scl_rising:
                return (False, row.get('edge'),
                        'dout changed during the READ capture phase without a filtered SCL rising edge')

        if in_read:
            previous_read = (outputs.get('dout'), scl_rising)
        else:
            previous_read = None

    if not seen_capture:
        return (None, None, 'no READ capture at a filtered SCL rising edge occurred in this trace')
