def decide(trace):
    positive = False
    negative = False

    for i, row in enumerate(trace):
        outputs = row.get('outputs', {})
        if not outputs.get('in_read_sequence', 0):
            continue

        rising = bool(outputs.get('filtered_scl_rising', 0))
        filtered_sda_low = bool(outputs.get('filtered_sda_low', 0))
        dout = outputs.get('dout')

        if rising:
            positive = True
            expected = 0 if filtered_sda_low else 1
            if dout != expected:
                return (False, row.get('edge'),
                        f"during READ at a filtered SCL rising edge, dout was {dout!r}; expected the stable filtered SDA value {expected}")
            continue

        if i == 0:
            continue
        previous = trace[i - 1]
        previous_outputs = previous.get('outputs', {})
        if not previous_outputs.get('in_read_sequence', 0):
            continue

        raw_line_changed = (
            row.get('inputs', {}).get('scl_i') != previous.get('inputs', {}).get('scl_i') or
            row.get('inputs', {}).get('sda_i') != previous.get('inputs', {}).get('sda_i')
        )
        filtered_sda_changed = (
            filtered_sda_low != bool(previous_outputs.get('filtered_sda_low', 0))
