            negative = True
            previous_dout = previous_outputs.get('dout')
            if dout != previous_dout:
                return (False, row.get('edge'),
                        "dout changed during READ without a filtered SCL rising edge")

    if not positive and not negative:
        return (None, None, "neither a READ filtered-SCL capture nor a qualifying non-capture line change occurred")
    if not positive:
        return (None, None, "only the no-update route case was observed; no READ filtered-SCL rising edge occurred")
    if not negative:
