def decide(trace):
    # The internal dSCL/dSDA state is observed through the declared busy route.
    # Probes are declared trace ports and are sampled like outputs.
    events = []
    for i in range(1, len(trace)):
        prev = trace[i - 1]['outputs']['filtered_sda_low']
        cur = trace[i]['outputs']['filtered_sda_low']
        if cur != prev:
            events.append(i)

    if not events:
        return (None, None, 'no filtered SDA transition occurred; the routed situation was not exercised')

    for n, i in enumerate(events):
        row = trace[i]
        busy = row['outputs']['busy']
        sda_low = row['outputs']['filtered_sda_low']
        scl_high = row['outputs']['filtered_scl_high']
        edge = row['edge']

        if not scl_high:
            prior_busy = trace[i - 1]['outputs']['busy']
            if busy != prior_busy:
                return (False, edge,
                        'busy changed on a filtered SDA transition while filtered SCL was low; it should hold its prior value')
            continue

        expected = 1 if sda_low else 0
        end = events[n + 1] if n + 1 < len(events) else len(trace)
        found = False
        for j in range(i, end):
            if trace[j]['outputs']['busy'] == expected:
                found = True
                break
        if not found:
            return (None, None,
                    f'filtered SDA transitioned while filtered SCL was high, but the trace ended before busy became {expected}')

    return (True, None, 'busy followed every filtered SDA transition while SCL was high and held across transitions while SCL was low')

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, eventually, worst

    def _transition_windows(direction):
        changed = edges(trace, "filtered_sda_low", direction)
        return after(
            trace,
            lambda r: r["edge"] in changed
            and r["outputs"].get("filtered_scl_high") == 1,
            until=TO_END,
        )

    rising_windows = _transition_windows("rise")
    falling_windows = _transition_windows("fall")

    if not rising_windows and not falling_windows:
        return (None, None, "no filtered SDA transition while filtered SCL was high")
    if not rising_windows or not falling_windows:
        return (None, None, "only one side of the busy transition signature was exercised")

    checks = []
    checks.extend(
        eventually(
            w,
            lambda r: r["outputs"].get("busy") == 1,
            strong=True,
            after_activation=True,
        )
        for w in rising_windows
    )
    checks.extend(
        eventually(
            w,
            lambda r: r["outputs"].get("busy") == 0,
            strong=True,
            after_activation=True,
        )
        for w in falling_windows
    )
    return worst(checks)

def decide(trace):
    positive = []
    negative = []

    for i in range(1, len(trace)):
        prev = trace[i - 1]['outputs'].get('filtered_sda_low')
        row = trace[i]
        now = row['outputs'].get('filtered_sda_low')
        if prev is None or now is None or prev == now:
            continue

        scl_high = row['outputs'].get('filtered_scl_high') == 1
        if scl_high:
            # A rising filtered_sda_low is filtered SDA high-to-low;
            # a falling one is filtered SDA low-to-high.
            target = 1 if now == 1 else 0
            positive.append((i, target))
        else:
            negative.append(i)

    if not positive or not negative:
        return (None, None,
                'the trace did not exercise both routed cases: busy response to a filtered SDA transition while SCL is high and busy hold while SCL is low')

    for i in negative:
        before = trace[i - 1]['outputs'].get('busy')
        at_event = trace[i]['outputs'].get('busy')
        if before is not None and at_event is not None and at_event != before:
            return (False, trace[i].get('edge'),
                    'busy changed on a filtered SDA transition while filtered SCL was low; the route states that busy holds its prior value in this case')

    undecided = False
    for i, target in positive:
        before = trace[i - 1]['outputs'].get('busy')
        if before is None:
            undecided = True
            continue
        if before == target:
            undecided = True
            continue

        response = None
        for j in range(i, len(trace)):
            value = trace[j]['outputs'].get('busy')
            prior = trace[j - 1]['outputs'].get('busy') if j > 0 else None
            if value != prior:
                response = (j, value)
                break

        if response is None:
            undecided = True
        elif response[1] != target:
            return (False, trace[response[0]].get('edge'),
                    f'busy changed to {response[1]!r} after the filtered SDA transition while filtered SCL was high; expected {target!r}')

    if undecided:
        return (None, None,
                'the routed busy response was not fully observable in this trace')
    return (True, None,
            'both routed cases were observed: busy changed appropriately when filtered SDA transitioned while SCL was high and held during a transition while SCL was low')

