def decide(trace):
    events = []

    for i, row in enumerate(trace):
        outputs = row.get('outputs', {})
        inputs = row.get('inputs', {})
        if inputs.get('ena') != 1:
            continue

        if outputs.get('start_condition') == 1:
            events.append((i, 'busy', 1, 'filtered START event', 'busy rises'))
        if outputs.get('stop_condition') == 1:
            events.append((i, 'busy', 0, 'filtered STOP event', 'busy falls'))
        if (outputs.get('sda_arbitration_check') == 1 and
                outputs.get('filtered_sda_low') == 1):
            events.append((i, 'al', 1, 'filtered SDA arbitration-loss event', 'al rises'))

    if not events:
        return (None, None, 'no qualifying filtered bus event occurred')

    for start, port, expected, event_name, effect_name in events:
        for i in range(start, len(trace)):
            current = trace[i].get('outputs', {}).get(port)
            previous = (trace[i - 1].get('outputs', {}).get(port)
                        if i > 0 else None)
            if current == expected and previous != expected:
                break
        else:
            edge = trace[start].get('edge')
            return (False, edge,
                    f'{event_name} was observed but {effect_name} was not detected on declared output {port}')

    return (True, None,
            f'all {len(events)} qualifying filtered bus event(s) produced their declared output effects')

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, eventually, worst

    def windows_for_probe(probe):
        rising = edges(trace, probe, "rise")
        return after(
            trace,
            lambda r: r["edge"] in rising,
            until=TO_END,
        )

    busy_rises = edges(trace, "busy", "rise")
    busy_falls = edges(trace, "busy", "fall")
    al_rises = edges(trace, "al", "rise")

    verdicts = []
    for w in windows_for_probe("start_condition"):
        verdicts.append(
            eventually(
                w,
                lambda r: r["edge"] in busy_rises,
                strong=True,
                after_activation=False,
            )
        )
    for w in windows_for_probe("stop_condition"):
        verdicts.append(
            eventually(
                w,
                lambda r: r["edge"] in busy_falls,
                strong=True,
                after_activation=False,
            )
        )
    for w in windows_for_probe("sda_arbitration_check"):
        verdicts.append(
            eventually(
                w,
                lambda r: r["edge"] in al_rises,
                strong=True,
                after_activation=False,
            )
        )

    return worst(verdicts)

