def decide(trace):
    from specflow.refmodel.temporal import after, throughout

    supported_cmds = (1, 2, 4, 8)

    def active(row):
        return (
            row['inputs'].get('cmd') in supported_cmds
            and row['inputs'].get('ena') == 1
            and row['outputs'].get('slave_wait_active') == 1
        )

    def clears(row):
        return row['outputs'].get('slave_wait_active') == 0

    def reset_abort(row):
        return (
            row['inputs'].get('nReset') == 0
            or row['inputs'].get('rst') == 1
        )

    windows = after(
        trace,
        active,
        until=clears,
        aborts=reset_abort,
    )

    if not windows:
        return (None, None, 'slave-wait condition never occurred')

    saw_complete_after_wait = False
    completion_edge = None

    for window in windows:
        paused = throughout(
            window,
            lambda row: row['outputs'].get('cmd_ack') == 0,
            after_activation=True,
        )
        if paused[0] is False:
            return paused
        if paused[0] is not True:
            continue

        if not window.closed or not window.rows:
            continue

        close_index = window.rows[-1]['index']
        later_ack = [
            row for row in trace
            if row['index'] > close_index
            and row['outputs'].get('cmd_ack') == 1
        ]
        if later_ack:
            saw_complete_after_wait = True
            completion_edge = later_ack[0]['edge']

    if not saw_complete_after_wait:
        return (None, None, 'slave-wait held without an observable post-wait command completion')

    return (
        True,
        completion_edge,
        'cmd_ack stayed low throughout slave-wait and appeared only after the wait cleared',
    )

