    def out(row, name, default=None):
        return row.get('outputs', {}).get(name, default)

    def in_value(row, name, default=None):
        return row.get('inputs', {}).get(name, default)

    def in_sequence(row):
        return any(out(row, p, 0) == 1 for p in (
            'in_start_sequence',
            'in_stop_sequence',
            'in_read_sequence',
            'in_write_sequence',
        ))

    def in_owned_timing_situation(row):
        return (
            in_value(row, 'ena') == 1
            and out(row, 'fsm_active', 0) == 1
            and in_sequence(row)
            and in_value(row, 'nReset') == 1
            and in_value(row, 'rst') == 0
            and out(row, 'al', 0) == 0
            and out(row, 'scl_sync_active', 0) == 0
        )

    transitions = []
    for i in range(1, len(trace)):
        previous = trace[i - 1]
        current = trace[i]
        changed = out(current, 'scl_oen') != out(previous, 'scl_oen')
        relevant = in_owned_timing_situation(previous) or in_owned_timing_situation(current)
        if changed and relevant:
            transitions.append((i, previous, current))

    if not transitions:
        return (None, None, 'no SCL output-enable phase transition occurred in an enabled bit-level sequence')

    for i, previous, current in transitions:
        if out(current, 'clk_en_asserted', 0) != 1:
            return (
                False,
                current.get('edge'),
                'scl_oen changed outside a counter-generated timing tick'
            )

    return (
        True,
        transitions[-1][2].get('edge'),
        'all observed scl_oen phase transitions in enabled sequences occurred on clk_en_asserted timing ticks'
    )

