            and out(row, 'scl_sync_active') == 0
            and not (out(row, 'scl_oen') == 1 and out(row, 'filtered_scl_high') == 0)
        )

    def closes(row):
        return not (
            out(row, 'ena') == 1
            and sequence_active(row)
            and out(row, 'nReset') == 1
            and out(row, 'rst') == 0
        )

    def aborts(row):
        return (
            out(row, 'nReset') == 0
            or out(row, 'rst') == 1
