        if current_owned:
            in_owned_sequence = True
        elif in_owned_sequence:
            # The sequence ended normally only when its design-driven probe
            # stopped being active while reset, arbitration loss, and clock
            # synchronization remained absent.
            i = inputs(row)
            o = outputs(row)
            voided = (
                i.get('nReset') != 1
                or i.get('rst') == 1
