def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    active = []
    for row in trace:
        if out(row, 'fsm_active') and row.get('inputs', {}).get('ena') == 1:
            active.append(row)

    if not active:
        return (None, None, 'bit-level timing operation did not occur')

    transitions = []
    previous = None
    for row in active:
        value = out(row, 'scl_oen')
        if value is None:
            continue
        if previous is not None and value != previous:
            transitions.append(row)
        previous = value

    if not transitions:
        return (None, None, 'no observable scl_oen phase transition occurred during bit-level timing operation')

    for row in transitions:
        pos = trace.index(row)
        timed = False
        for j in (pos - 1, pos, pos + 1):
            if 0 <= j < len(trace):
                candidate = trace[j]
                if (out(candidate, 'clk_en_asserted') == 1 or
                        out(candidate, 'timing_counter_expired') == 1):
                    timed = True
                    break
        if not timed:
            return (False, row.get('edge'),
                    'scl_oen transitioned during active timing without a declared timing-enable or counter-expiry event')

    return (True, transitions[-1].get('edge'),
            'all observed scl_oen phase transitions during active timing were associated with the declared counter timing event')

def decide(trace):
    sequence_probes = (
        'in_start_sequence',
        'in_stop_sequence',
        'in_read_sequence',
        'in_write_sequence',
    )

    def out(row, name):
        return row.get('outputs', {}).get(name)

    def inp(row, name):
        return row.get('inputs', {}).get(name)

    def active(row):
        return bool(out(row, 'fsm_active')) or any(
            bool(out(row, name)) for name in sequence_probes
        )

    intervals = []
    start = None
    for i, row in enumerate(trace):
        voided = inp(row, 'nReset') == 0 or inp(row, 'rst') == 1 or bool(out(row, 'al'))
        live = active(row) and inp(row, 'ena') == 1 and not voided
        if live and start is None:
            start = i
        elif not live and start is not None:
            intervals.append((start, i - 1))
            start = None
    if start is not None:
        intervals.append((start, len(trace) - 1))

    if not intervals:
        return (None, None, 'bit-level timing operation never occurred')

    saw_transition = False
    last_transition_edge = None
    for start, end in intervals:
        # A trace beginning or ending inside a transaction does not provide
        # enough evidence to judge that transaction.
        if start == 0 or end == len(trace) - 1:
            continue

        reload_value = inp(trace[start], 'clk_cnt')
        if not isinstance(reload_value, int) or reload_value < 0:
            continue

        elapsed = 0
        transition_found = False
        for i in range(start, end + 1):
            if i > start:
                elapsed += trace[i - 1].get('held', 1)
            changed = out(trace[i], 'scl_oen') != out(trace[i - 1], 'scl_oen')
            if changed:
                saw_transition = True
                transition_found = True
                last_transition_edge = trace[i].get('edge')
                if elapsed < reload_value:
                    return (
                        False,
                        trace[i].get('edge'),
                        f'scl_oen phase transition occurred after {elapsed} clock edges, before the clk_cnt-loaded interval of {reload_value} edges'
                    )

        if not transition_found:
            return (
                False,
                trace[end].get('edge'),
                'active bit-level timing completed without a declared scl_oen phase transition'
            )

    if not saw_transition:
        return (None, None, 'the trace did not contain a complete observable bit-level timing interval')
    return (True, last_transition_edge, 'scl_oen phase transitions respected the clk_cnt-derived decrement interval')

