    from specflow.refmodel.temporal import WHILE_ACTIVE, after, throughout, worst

    def applies(row):
        return (
            row['inputs'].get('ena') == 1
            and row['outputs'].get('timing_counter_expired') == 1
        )

    windows = after(trace, applies, until=WHILE_ACTIVE)
    return worst([
        throughout(
            window,
            lambda row: row['outputs'].get('clk_en_asserted') == 1,
            after_activation=False,
        )
        for window in windows
    ])

def decide(trace):
    def value(row, port):
        return row.get('outputs', {}).get(port)

    activations = []
    previous_active = False
    for row in trace:
        active = (
            value(row, 'ena') == 1
            if 'ena' in row.get('outputs', {})
            else row.get('inputs', {}).get('ena') == 1
        ) and value(row, 'timing_counter_expired') == 1
        if active and not previous_active:
            activations.append(row)
        previous_active = active

    if not activations:
        return (None, None, 'timing counter did not expire while ena was high')

    for row in activations:
        if value(row, 'clk_en_asserted') != 1:
            return (
                False,
                row.get('edge'),
                'When the counter expires, the module asserts `clk_en`; '
                '`clk_en_asserted` was not high at the expiry state'
            )

    return (
        True,
        activations[0].get('edge'),
        'For every enabled timing-counter expiry, `clk_en_asserted` was high '
        'as required by the clause'
    )

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, eventually, worst

    def expires(row):
        return (
            row['inputs'].get('ena') == 1
            and row['outputs'].get('timing_counter_expired') == 1
        )

    windows = after(trace, expires, until=TO_END)
    return worst([
        eventually(
            window,
            lambda row: row['outputs'].get('clk_en_asserted') == 1,
            strong=True,
            after_activation=False,
        )
        for window in windows
    ])

