def decide(trace):
    sequence_probes = (
        'in_start_sequence',
        'in_stop_sequence',
        'in_read_sequence',
        'in_write_sequence',
    )

    def out(row, name, default=0):
        return row.get('outputs', {}).get(name, default)

    def inputs(row, name, default=0):
        return row.get('inputs', {}).get(name, default)

    def supported_active(row):
        return any(out(row, probe) == 1 for probe in sequence_probes)

    def reset_inactive(row):
        return inputs(row, 'nReset', 1) == 1 and inputs(row, 'rst', 0) == 0

    activation_edges = []
    for row in trace:
        if (supported_active(row) and reset_inactive(row)
                and inputs(row, 'ena', 0) == 1
                and out(row, 'clk_en_asserted') == 1):
            activation_edges.append(row.get('edge'))

    if not activation_edges:
        return (None, None,
                'no active supported command reached an asserted clk_en timing tick')

    violations = []
    for i in range(1, len(trace)):
        previous = trace[i - 1]
        current = trace[i]

        if out(previous, 'scl_oen') == out(current, 'scl_oen'):
            continue
        if not (supported_active(previous) or supported_active(current)):
            continue
        if not (reset_inactive(previous) and reset_inactive(current)):
            continue

        if out(current, 'clk_en_asserted') != 1:
            violations.append(current)

    if violations:
        row = violations[0]
        return (False, row.get('edge'),
                'scl_oen changed to a different timing phase while clk_en was not asserted')

    return (True, activation_edges[0],
            'all observed scl_oen timing-phase changes occurred with clk_en asserted')

def decide(trace):
    sequence_probes = (
        'in_start_sequence',
        'in_stop_sequence',
        'in_read_sequence',
        'in_write_sequence',
    )

    def active(row):
        outputs = row.get('outputs', {})
        return any(outputs.get(name) == 1 for name in sequence_probes)

    transitions = []
    saw_active = False

    for i in range(1, len(trace)):
        previous = trace[i - 1]
        current = trace[i]

        if active(previous) or active(current):
            saw_active = True

        if previous.get('inputs', {}).get('ena') != 1 or current.get('inputs', {}).get('ena') != 1:
            continue
        if not (active(previous) or active(current)):
            continue

        previous_scl_oen = previous.get('outputs', {}).get('scl_oen')
        current_scl_oen = current.get('outputs', {}).get('scl_oen')
        if previous_scl_oen != current_scl_oen:
            transitions.append((current, current.get('outputs', {}).get('clk_en_asserted') == 1))

    if not saw_active:
        return (None, None, 'no active supported START, STOP, READ, or WRITE sequence occurred')

    for row, timing_enabled in transitions:
        if not timing_enabled:
            return (False, row.get('edge'), 'scl_oen changed phase while clk_en was not asserted')

    if not transitions:
        return (None, None, 'no active sda/scl phase transition was observable on scl_oen')

    return (True, transitions[-1][0].get('edge'), 'all observed scl_oen phase changes occurred with clk_en asserted')

def decide(trace):
    def out(row, name, default=0):
        return row.get('outputs', {}).get(name, default)

    def inp(row, name, default=0):
        return row.get('inputs', {}).get(name, default)

    sequence_probes = (
        'in_start_sequence',
        'in_stop_sequence',
        'in_read_sequence',
        'in_write_sequence',
    )

    def active(row):
        return inp(row, 'ena', 0) == 1 and any(
            out(row, probe) == 1 for probe in sequence_probes
        )

    activated = []
    violations = []
    advances = []

    for i in range(1, len(trace)):
        previous = trace[i - 1]
        current = trace[i]

        prev_active = active(previous)
        curr_active = active(current)
        changed = (
            out(previous, 'scl_oen') != out(current, 'scl_oen')
        )

        if curr_active and out(current, 'clk_en_asserted') == 1:
            activated.append(current)
            if changed:
                advances.append(current)
            else:
                violations.append((current, 'the FSM did not advance its observable timing phase on an asserted clk_en tick'))

        if changed and (prev_active or curr_active):
            if out(current, 'clk_en_asserted') != 1:
                violations.append((current, 'scl_oen changed to a different timing phase while clk_en was not asserted'))

    if not activated:
        return (None, None, 'no active supported command reached an asserted clk_en timing tick')

    if violations:
        row, detail = violations[0]
        return (False, row.get('edge'), detail)

    if not advances:
        return (None, activated[0].get('edge'), 'no observable scl_oen phase advance was available to decide')

    return (True, advances[0].get('edge'), 'each observed active timing-tick phase advance occurred with clk_en asserted')

def decide(trace):
    def value(row, name, default=0):
        return row.get('outputs', {}).get(name, default)

    sequence_probes = (
        'in_start_sequence',
        'in_stop_sequence',
        'in_read_sequence',
        'in_write_sequence',
    )

    def active(row):
        return (
            row.get('inputs', {}).get('ena', 0) == 1
            and any(value(row, probe) == 1 for probe in sequence_probes)
            and row.get('inputs', {}).get('nReset', 1) == 1
            and row.get('inputs', {}).get('rst', 0) == 0
        )

    observed_transition = None

    for i in range(1, len(trace)):
        previous = trace[i - 1]
        current = trace[i]

        if not (active(previous) or active(current)):
            continue

        if value(previous, 'scl_oen') == value(current, 'scl_oen'):
            continue

        observed_transition = current
        if value(current, 'clk_en_asserted') != 1:
            return (
                False,
                current.get('edge'),
                'scl_oen changed to the next observable timing phase while clk_en was not asserted'
            )

    if observed_transition is None:
        return (
            None,
            None,
            'no observable scl_oen timing-phase transition occurred during an active supported sequence'
        )

    return (
        True,
        observed_transition.get('edge'),
        'each observed scl_oen timing-phase transition during an active supported sequence occurred with clk_en asserted'
    )

