def decide(trace):
    from specflow.refmodel.temporal import WHILE_ACTIVE, after, throughout

    def reset_clear(row):
        inputs = row.get('inputs', {})
        return inputs.get('nReset') == 1 and inputs.get('rst') == 0

    active_probes = (
        'in_start_sequence',
        'in_stop_sequence',
        'in_read_sequence',
        'in_write_sequence',
    )

    def active_command(row):
        outputs = row.get('outputs', {})
        return any(outputs.get(p) == 1 for p in active_probes)

    def disabled_active(row):
        return reset_clear(row) and row.get('inputs', {}).get('ena') == 0 and active_command(row)

    windows = after(trace, disabled_active, until=WHILE_ACTIVE)
    if not windows:
        return (None, None, 'no active supported command was observed while ena was low')

    enabled_completion = False
    for window in windows:
        rows = window.rows
        if not rows:
            continue
        start = rows[0]['index']
        end = rows[-1]['index']
        was_enabled_active = False
        for row in trace:
            if row['index'] < start:
                continue
            if row['index'] >= end and reset_clear(row):
                inputs = row.get('inputs', {})
                outputs = row.get('outputs', {})
                if inputs.get('ena') == 1 and active_command(row):
                    was_enabled_active = True
                if inputs.get('ena') == 1 and outputs.get('cmd_ack') == 1 and was_enabled_active:
                    enabled_completion = True
                    break
        if enabled_completion:
            break

    if not enabled_completion:
        return (None, None, 'only the disabled side was observed; no enabled completion was shown')

    verdicts = [
        throughout(
            window,
            lambda row: row.get('outputs', {}).get('cmd_ack') == 0,
            after_activation=False,
        )
        for window in windows
    ]
    for verdict in verdicts:
        if verdict[0] is False:
            return (False, verdict[1], 'cmd_ack asserted while ena was low; expected no command-complete pulse while the core was disabled')
    if any(verdict[0] is None for verdict in verdicts):
        return (None, None, 'the disabled interval was incomplete in the trace; could not establish that cmd_ack stayed low throughout')
    return (True, None, 'cmd_ack remained low while ena was low during an active command, while enabled completion was also observed')

def decide(trace):
    def inp(row, name):
        return row.get('inputs', {}).get(name)

    def out(row, name):
        return row.get('outputs', {}).get(name)

    def reset_asserted(row):
        return inp(row, 'nReset') == 0 or inp(row, 'rst') == 1

    phase = None
    saw_disabled = False
    unresolved = False
    completed = False

    for row in trace:
        if reset_asserted(row):
            phase = None
            continue

        active = out(row, 'fsm_active') == 1
        enabled = inp(row, 'ena') == 1
        disabled = inp(row, 'ena') == 0

        if phase is None:
            if active and disabled:
                saw_disabled = True
                phase = 'disabled'
                if out(row, 'cmd_ack') == 1:
                    return (False, row.get('edge'),
                            'cmd_ack asserted while ena was low during an active command')
            continue

        if phase == 'disabled':
            if active and disabled:
                if out(row, 'cmd_ack') == 1:
                    return (False, row.get('edge'),
                            'cmd_ack asserted while ena was low during an active command')
            elif active and enabled:
                phase = 'enabled'
                if out(row, 'cmd_ack') == 1:
                    completed = True
                    phase = None
            elif not active:
                unresolved = True
                phase = None
            continue

        if phase == 'enabled':
            if enabled and out(row, 'cmd_ack') == 1:
                completed = True
                phase = None
            elif active and disabled:
                phase = 'disabled'
                if out(row, 'cmd_ack') == 1:
                    return (False, row.get('edge'),
                            'cmd_ack asserted while ena was low during an active command')
            elif not active:
                unresolved = True
                phase = None

    if phase is not None:
        unresolved = True

    if not saw_disabled:
        return (None, None,
                'no active command was observed with ena low and reset inactive')
    if unresolved:
        return (None, None,
                'cmd_ack remained low while ena was low, but the trace did not show '
                'the same active command re-enabled and completing')
    if not completed:
        return (None, None,
                'the disabled-side observation occurred, but no re-enabled completion '
                'was observed')
    return (True, None,
            'cmd_ack remained low while ena was low and asserted after the active '
            'command was re-enabled')

def decide(trace):
    from specflow.refmodel.temporal import WHILE_ACTIVE, after, throughout

    def reset_not_asserted(row):
        inputs = row.get('inputs', {})
        return inputs.get('nReset') == 1 and inputs.get('rst') == 0

    active_probes = (
        'fsm_active',
        'in_start_sequence',
        'in_stop_sequence',
        'in_read_sequence',
        'in_write_sequence',
    )

    def active_supported_command(row):
        outputs = row.get('outputs', {})
        return any(outputs.get(name) == 1 for name in active_probes)

    def disabled_active(row):
        return (
            reset_not_asserted(row)
            and row.get('inputs', {}).get('ena') == 0
            and active_supported_command(row)
        )

    windows = after(trace, disabled_active, until=WHILE_ACTIVE)
    if not windows:
        return (None, None, 'no active supported command was observed while ena was low')

    for window in windows:
        verdict = throughout(
            window,
            lambda row: row.get('outputs', {}).get('cmd_ack') == 0,
            after_activation=False,
        )
        if verdict[0] is False:
            return (
                False,
                verdict[1],
                'cmd_ack asserted while ena was low during an active supported command; normal FSM timing was not stalled',
            )
        if verdict[0] is None:
            return (
                None,
                None,
                'the disabled active-command interval was incomplete; could not establish that cmd_ack remained low',
            )

    enabled_completion = False
    had_enabled_active = False
    for row in trace:
        if not reset_not_asserted(row):
            had_enabled_active = False
            continue
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})
        if inputs.get('ena') == 1 and active_supported_command(row):
            had_enabled_active = True
        if inputs.get('ena') == 1 and outputs.get('cmd_ack') == 1 and had_enabled_active:
            enabled_completion = True
            break

    if not enabled_completion:
        return (None, None, 'the disabled side was observed, but no enabled active-command completion was shown')

    return (
        True,
        None,
        'cmd_ack remained low while ena disabled an active supported command, while enabled completion was also observed',
    )

def decide(trace):
    from specflow.refmodel.temporal import after, throughout, worst

    def outputs(row):
        return row.get('outputs', {})

    def inputs(row):
        return row.get('inputs', {})

    def reset_asserted(row):
        i = inputs(row)
        return i.get('nReset') == 0 or i.get('rst') == 1

    active_probes = (
        'in_start_sequence',
        'in_stop_sequence',
        'in_read_sequence',
        'in_write_sequence',
    )

    def active_supported_command(row):
        o = outputs(row)
        return any(o.get(name) == 1 for name in active_probes)

    def disabled_incomplete_command(row):
        i = inputs(row)
        o = outputs(row)
        return (
            not reset_asserted(row)
            and i.get('ena') == 0
            and active_supported_command(row)
            and o.get('cmd_ack') == 0
        )

    def reenabled(row):
        return inputs(row).get('ena') == 1

    windows = after(
        trace,
        disabled_incomplete_command,
        until=reenabled,
        aborts=reset_asserted,
    )

    if not windows:
        return (None, None, 'no active incomplete supported command was observed with ena low')

    stalled = worst([
        throughout(
            w,
            lambda row: outputs(row).get('cmd_ack') == 0,
            after_activation=False,
        )
        for w in windows
    ])

    if stalled[0] is False:
        return (
            False,
            stalled[1],
            'cmd_ack asserted while ena was low during an active incomplete command; normal FSM timing was not stalled',
        )
    if stalled[0] is None:
        return (
            None,
            None,
            'the disabled active-command window was incomplete or reset-aborted; the stall could not be decided',
        )

    saw_enabled_active = False
    enabled_completion_edge = None
    for row in trace:
        if reset_asserted(row):
            saw_enabled_active = False
            continue
        i = inputs(row)
        o = outputs(row)
        if i.get('ena') == 1 and active_supported_command(row):
            saw_enabled_active = True
        if i.get('ena') == 1 and saw_enabled_active and o.get('cmd_ack') == 1:
            enabled_completion_edge = row.get('edge')
            break

    if enabled_completion_edge is None:
        return (
            None,
            None,
            'cmd_ack remained low during the disabled interval, but the corresponding enabled completion side was not observed',
        )

    return (
        True,
        enabled_completion_edge,
        'cmd_ack remained low while ena disabled an active incomplete command, while enabled operation later completed with cmd_ack',
    )

