from specflow.refmodel.temporal import TO_END, after, eventually, worst


def _value(row, port):
    return row['outputs'].get(port, row['inputs'].get(port))


def _any(conditions):
    def predicate(row):
        return any(all(_value(row, port) == value for port, value in condition.items())
                   for condition in conditions)
    return predicate


def decide(trace):
    # The specification provides no authoritative numeric encoding table for
    # cmd, so use the declared probe that identifies execution of WRITE.
    writing = lambda row: _value(row, 'in_write_sequence') == 1
    closes = _any([{'cmd_ack': 1}])
    aborts = _any([
        {'al': 1},
        {'nReset': 0},
        {'rst': 1},
    ])

    windows = after(trace, writing, until=closes, aborts=aborts)
    return worst([
        eventually(
            window,
            lambda row: _value(row, 'sda_arbitration_check') == 1,
            strong=True,
            after_activation=True,
        )
        for window in windows
    ])

from specflow.refmodel.temporal import after, edges, eventually, worst


def decide(trace):
    def holds(cond):
        def predicate(row):
            for port, value in cond.items():
                if port in row['outputs']:
                    actual = row['outputs'][port]
                else:
                    actual = row['inputs'].get(port)
                if actual != value:
                    return False
            return True
        return predicate

    write_entries = edges(trace, 'in_write_sequence', 'rise')
    windows = after(
        trace,
        lambda row: row['edge'] in write_entries,
        until=holds({'cmd_ack': 1}),
        aborts=lambda row: (
            holds({'al': 1})(row)
            or holds({'nReset': 0})(row)
            or holds({'rst': 1})(row)
        )
    )

    return worst([
        eventually(
            window,
            holds({'sda_arbitration_check': 1}),
            strong=True,
            after_activation=True
        )
        for window in windows
    ])

