def _any(conditions):
    def predicate(row):
        return any(all(_value(row, port) == value for port, value in condition.items())
                   for condition in conditions)
    return predicate


def decide(trace):
    # The command encoding is not supplied by an authoritative port encoding
    # table.  The declared probe identifies the actual WRITE operation without
    # inventing a numeric cmd value.
    write_starts = edges(trace, 'in_write_sequence', 'rise')
    opens = lambda row: row['edge'] in write_starts

    closes = _any([{'cmd_ack': 1}])
    aborts = _any([
        {'al': 1},
        {'nReset': 0},
        {'rst': 1},
    ])

    windows = after(trace, opens, until=closes, aborts=aborts)
    return worst([
        eventually(
            window,
            lambda row: _value(row, 'sda_arbitration_check') == 1,
            strong=True,
            after_activation=True,
        )
        for window in windows
    ])

