def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, eventually, worst

    def holds(cond):
        def predicate(row):
            values = {}
            values.update(row.get('inputs', {}))
            values.update(row.get('outputs', {}))
            return all(values.get(port) == value for port, value in cond.items())
        return predicate

    def any_alternative(alternatives):
        predicates = [holds(condition) for condition in alternatives]
        return lambda row: any(predicate(row) for predicate in predicates)

    # The command encoding is intentionally not used: no authoritative
    # encoding table is present. These declared probes and port levels identify
    # the stable WRITE arbitration-check phase instead.
    applies = lambda row: (
        holds({'ena': 1, 'din': 1})(row)
        and holds({'in_write_sequence': 1})(row)
        and holds({
            'filtered_sda_low': 1,
            'scl_oen': 1,
            'sda_arbitration_check': 1,
            'sda_oen': 1,
        })(row)
    )

    windows = after(
        trace,
        applies,
        until=any_alternative([{'scl_oen': 0}]),
        aborts=any_alternative([{'nReset': 0}, {'rst': 1}]),
    )

    return worst([
        eventually(
            window,
            lambda row: row.get('outputs', {}).get('al') == 1,
            strong=True,
            after_activation=True,
        )
        for window in windows
    ])

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, eventually, worst

    def holds(cond):
        def predicate(row):
            values = row.get('outputs', {})
            inputs = row.get('inputs', {})
            return all(values.get(port, inputs.get(port)) == value
                       for port, value in cond.items())
        return predicate

    def any_of(alternatives):
        predicates = [holds(condition) for condition in alternatives]
        return lambda row: any(predicate(row) for predicate in predicates)

    # The declared signature identifies arbitration checking without relying
    # on an unspecified numeric command encoding.
    arbitration_loss = holds({
        'filtered_sda_low': 1,
        'scl_oen': 1,
        'sda_arbitration_check': 1,
        'sda_oen': 1,
    })

    windows = after(
        trace,
        arbitration_loss,
        until=holds({'scl_oen': 0}),
        aborts=any_of([{'nReset': 0}, {'rst': 1}]),
    )

    return worst([
        eventually(
            window,
            lambda row: row.get('outputs', {}).get('al') == 1,
            strong=True,
            after_activation=True,
        )
        for window in windows
    ])

