        return (row.get('inputs', {}).get('nReset') == 0 or
                row.get('inputs', {}).get('rst') == 1)

    def non_stop_active(row):
        return (out(row, 'fsm_active') == 1 and
                (out(row, 'in_start_sequence') == 1 or
                 out(row, 'in_read_sequence') == 1 or
                 out(row, 'in_write_sequence') == 1))

    activations = []
    previous_stop = 0
    for i, row in enumerate(trace):
        stop = 1 if out(row, 'stop_condition') == 1 else 0
        rising_stop = stop == 1 and previous_stop == 0
        if rising_stop and non_stop_active(row) and not reset(row):
            activations.append(i)
        previous_stop = stop

    if not activations:
        return (None, None, 'no STOP condition occurred during an active START, READ, or WRITE sequence')

    for start in activations:
        for j in range(start + 1, len(trace)):
            row = trace[j]
            if reset(row):
