def decide(trace):
    # `cmd_ack` is the declared output route associated with command decoding,
    # but its pulse behavior belongs to the linked command-completion
    # requirement, not this obligation.
    _observed_cmd_ack = any(
        'cmd_ack' in row.get('outputs', {})
        for row in trace
    )
