            'the obligation states command decoding but licenses no independent output effect; cmd_ack is owned by the command-completion requirement')

def decide(trace):
    def out(row, name, default=None):
        return row.get('outputs', {}).get(name, default)

    def probe(row, name):
        return out(row, name, 0) == 1

    # These are the values supplied by the normalized activation.
    commands = {0, 1, 2, 4, 8}
    activations = []
    previous = False
    for row in trace:
        active = probe(row, 'in_idle') and row.get('inputs', {}).get('cmd') in commands
        if active and not previous:
            activations.append(row)
        previous = active

    if not activations:
        return (None, None, 'the command FSM never reached idle with a defined command value')

    for activation in activations:
        cmd = activation.get('inputs', {}).get('cmd')
        start = activation.get('index', 0)
        accepted = None
        for row in trace:
            if row.get('index', 0) <= start:
                continue
            if probe(row, 'in_idle') and probe(row, 'clk_en_asserted'):
                accepted = row
                break
        if accepted is None:
            continue

        accepted_index = accepted.get('index', 0)
        later = [r for r in trace if r.get('index', 0) > accepted_index]

        if cmd == 1:
            phase = [r for r in later if probe(r, 'in_start_sequence')]
            if not phase:
                return (False, accepted.get('edge'), 'START was accepted in idle but no START decode phase occurred')
            matching = [r for r in phase
                        if out(r, 'sda_oen') == 0 and out(r, 'scl_oen') == 1]
            if not matching:
                return (False, phase[0].get('edge'), 'START decode phase occurred without its declared SDA-low/SCL-released signature')

        elif cmd == 2:
            phase = [r for r in later if probe(r, 'in_stop_sequence')]
            if not phase:
                return (False, accepted.get('edge'), 'STOP was accepted in idle but no STOP decode phase occurred')
            matching = [r for r in phase if out(r, 'sda_oen') in (0, 1)]
            if not matching:
                return (False, phase[0].get('edge'), 'STOP decode phase produced no observable output state')

        elif cmd == 8:
            phase = [r for r in later if probe(r, 'in_read_sequence')]
            if not phase:
                return (False, accepted.get('edge'), 'READ was accepted in idle but no READ decode phase occurred')
            matching = [r for r in phase if out(r, 'sda_oen') == 1]
            if not matching:
                return (False, phase[0].get('edge'), 'READ decode phase did not keep SDA released')

        elif cmd == 4:
            phase = [r for r in later if probe(r, 'in_write_sequence')]
            if not phase:
                return (False, accepted.get('edge'), 'WRITE was accepted in idle but no WRITE decode phase occurred')
            din = accepted.get('inputs', {}).get('din')
            expected = 0 if din == 0 else 1
            matching = [r for r in phase if out(r, 'sda_oen') == expected]
            if not matching:
                return (False, phase[0].get('edge'), 'WRITE decode phase did not follow din on sda_oen')

        else:
            phases = [r for r in later if any(
                probe(r, p) for p in ('in_start_sequence', 'in_stop_sequence',
                                      'in_read_sequence', 'in_write_sequence'))]
            acks = [r for r in later if out(r, 'cmd_ack') == 1]
            if phases or acks:
                row = (phases or acks)[0]
                return (False, row.get('edge'), 'no-operation command was accepted but produced a command phase or acknowledge')

    return (True, None, 'each observed idle command was decoded to its corresponding command branch or no operation')

