        'in_stop_sequence',
        'in_read_sequence',
        'in_write_sequence',
    )

    def state(row, name):
        return row.get('outputs', {}).get(name, 0) == 1

    attempts = []
    previous_key = None

    for i, row in enumerate(trace):
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})
        if 'cmd' not in inputs or 'in_idle' not in outputs:
            continue

        idle = state(row, 'in_idle')
        key = (idle, inputs.get('cmd')) if idle else None
        if not idle or key == previous_key:
            previous_key = key
            continue

        previous_key = key
        attempts.append((i, inputs.get('cmd')))

