                break

            active = [name for name in states if state(row, name)]
            if len(active) > 1:
                return (False, row.get('edge'), 'more than one command-sequence state is active')

            if active:
                first_sequence = (active[0], row.get('edge'))
                break

            if not state(row, 'in_idle'):
                return (False, row.get('edge'), 'the FSM left idle without entering a declared command sequence')
            j += 1

