            continue

        if j < len(trace) and trace[j].get('inputs', {}).get('cmd') != command:
            continue

        if start < len(trace) and state(trace[start], 'in_idle'):
            continue

    return (True, None, 'each observed idle command remained in idle or entered one declared command-sequence state')

