        return (None, None, "START sequence never began")

    positions = {row["index"]: i for i, row in enumerate(trace)}
    failures = []
    incomplete = False

    for window in windows:
        release_pos = None
        action_pos = None

        # Find a released-both-lines state followed by the required SDA
        # high-to-low action.  The intervening states must keep SCL released
        # and SDA high, so a later transient cannot satisfy the ordering.
        for row in window.rows:
            pos = positions.get(row["index"])
            if pos is None:
                continue

            if (
                out(row, "scl_oen") == 1
                and out(row, "sda_oen") == 1
                and release_pos is None
            ):
                release_pos = pos
                continue

            if release_pos is None or pos <= release_pos or pos == 0:
                continue

            previous = trace[pos - 1]
            sda_fell = (
                out(previous, "sda_oen") == 1
                and out(row, "sda_oen") == 0
            )
