                    out(r, "sda_oen") == 1
                    for r in trace[release_pos:pos]
                ):
                    action_pos = pos
                    break

        if action_pos is not None:
            continue

        if not window.closed:
            incomplete = True
            continue

        edge = window.rows[-1]["edge"] if window.rows else window.edge
        failures.append(
            (
                False,
                edge,
                "START window completed without a released-both-lines phase followed by SDA drive-low while SCL remained released/high",
            )
        )

    if failures:
        return failures[0]
    if incomplete:
        return (None, None, "START sequence window was incomplete")
    return (
        True,
        None,
        "START released SDA and SCL, then drove SDA low while SCL remained high",
