        inputs_hold(row, {'cmd': 1, 'ena': 1})
        and any_outputs([{'start_condition': 1}])(row)
    )
    aborts = any_outputs([{'nReset': 0}, {'rst': 1}])

    windows = after(
        trace,
        opens,
        until=any_outputs([{'cmd_ack': 1}]),
        aborts=aborts,
    )

    follows = True
    verdicts = []

    for window in windows:
        completion = eventually(
            window,
            lambda row: (
                row['outputs'].get('scl_oen') == 0
                and row['outputs'].get('in_idle') == 1
                and row['outputs'].get('cmd_ack') == 1
                and row.get('held') == 1
            ),
            strong=True,
            after_activation=follows,
        )
        verdicts.append(completion)

        ack_rows = [
            row for row in window.rows
            if row['outputs'].get('cmd_ack') == 1
        ]
        if not ack_rows:
            continue

        ack = ack_rows[0]
        if ack.get('held') != 1:
            verdicts.append((
                False,
                ack.get('edge'),
                'cmd_ack was not asserted for exactly one clock cycle'
            ))
            continue

        next_index = ack.get('index', -1) + 1
