def decide(trace):
    completions = []
    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        prev_read = prev.get('outputs', {}).get('in_read_sequence') == 1
        now_read = row.get('outputs', {}).get('in_read_sequence') == 1
        if not (prev_read and not now_read):
            continue

        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})
        if (inputs.get('nReset') == 0 or inputs.get('rst') == 1
                or outputs.get('al') == 1):
            continue

        result = None
        for later in trace[i:]:
            later_inputs = later.get('inputs', {})
            later_outputs = later.get('outputs', {})
            if (later_inputs.get('nReset') == 0
                    or later_inputs.get('rst') == 1
                    or later_outputs.get('al') == 1):
                result = (None, later.get('edge'),
                          'read completion was aborted by reset or arbitration loss')
                break
            if later_outputs.get('cmd_ack') == 1:
                result = (True, later.get('edge'),
                          'cmd_ack asserted after the read bit cycle completed')
                break
        if result is None:
            result = (False, row.get('edge'),
                      'read bit cycle completed but cmd_ack did not assert')
        completions.append(result)

    if not completions:
        return (None, None,
                'the read bit cycle did not complete in this trace')
    for verdict in completions:
        if verdict[0] is False:
            return verdict
    for verdict in completions:
        if verdict[0] is True:
            return verdict
    return (None, None,
            'all observed read completions were aborted by reset or arbitration loss')

def decide(trace):
    completions = []
    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        prev_out = prev.get('outputs', {})
        out = row.get('outputs', {})

        # The declared READ-state probe qualifies the situation.  The
        # released-to-driven SCL transition is the read-bit completion
        # signature, not a guessed command encoding.
        if prev_out.get('in_read_sequence') != 1:
            continue
        if out.get('in_read_sequence') != 1:
            continue
        if not (prev_out.get('scl_oen') == 1 and out.get('scl_oen') == 0):
            continue

        aborted = False
        for later in trace[i + 1:]:
            later_inputs = later.get('inputs', {})
            later_outputs = later.get('outputs', {})
            if (later_inputs.get('nReset') == 0
                    or later_inputs.get('rst') == 1
                    or later_outputs.get('al') == 1):
                aborted = True
                break
            if later_outputs.get('cmd_ack') == 1:
                completions.append(
                    (True, later.get('edge'),
                     'cmd_ack asserted after the completed READ bit cycle'))
                break
        else:
            completions.append(
                (None, row.get('edge'),
                 'READ bit cycle completed; trace ended before cmd_ack could be observed'))

        if aborted:
            completions.append(
                (None, row.get('edge'),
                 'READ completion attempt was aborted by reset or arbitration loss'))

    if not completions:
        return (None, None,
                'the READ bit-cycle completion signature did not occur')

    for verdict in completions:
        if verdict[0] is False:
            return verdict
    for verdict in completions:
        if verdict[0] is True:
            return verdict
    return completions[0]

