def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, sequence, worst

    def out(row, port):
        return row.get('outputs', {}).get(port)

    def inp(row, port):
        return row.get('inputs', {}).get(port)

    def aborts(row):
        return (
            out(row, 'al') == 1
            or inp(row, 'nReset') == 0
            or inp(row, 'rst') == 1
        )

    # The cmd encoding is not supplied in an authoritative encoding table.
    # The declared WRITE-state probe is therefore used as the trigger.
    def write_active(row):
        return inp(row, 'ena') == 1 and out(row, 'in_write_sequence') == 1

    windows = after(
        trace,
        write_active,
        until=lambda row: out(row, 'cmd_ack') == 1,
        aborts=aborts,
    )

    if not windows:
        return (None, None, 'the WRITE activation never occurred')

    scl_falls = edges(trace, 'scl_oen', 'fall')
    results = []

    for w in windows:
        high_phase = lambda row: out(row, 'scl_oen') == 1
        pulled_low = lambda row: row.get('edge') in scl_falls
        terminal = lambda row: (
            out(row, 'scl_oen') == 0
            and out(row, 'in_idle') == 1
            and out(row, 'cmd_ack') == 1
        )

        results.append(
            sequence(
                w,
                high_phase,
                pulled_low,
                terminal,
                strong=True,
                after_activation=True,
            )
        )

        ack_rows = [r for r in w.rows if out(r, 'cmd_ack') == 1]
        if ack_rows:
            bad = [r for r in ack_rows if r.get('held') != 1]
            if bad:
                results.append((
                    False,
                    bad[0].get('edge'),
                    'cmd_ack was held for %s edges; the obligation requires a one-clock pulse'
                    % bad[0].get('held'),
                ))
            else:
                results.append((
                    True,
                    ack_rows[0].get('edge'),
                    'cmd_ack pulsed for exactly one clock at WRITE completion',
                ))

    return worst(results)

