            row.get('edge') in write_rises
            and inp(row, 'ena') == 1
            and inp(row, 'cmd') == 4
        )

    windows = after(
        trace,
        write_entry,
        until=lambda row: out(row, 'cmd_ack') == 1,
        aborts=aborted,
    )

    if not windows:
        return (None, None, 'the WRITE-sequence entry transition never occurred')

    verdicts = []

    for window in windows:
        rows = list(window.rows)
        body = rows[1:]  # effect_follows is true: inspect states after entry

        if not body:
            verdicts.append((None, window.edge, 'the WRITE window contains no post-entry state'))
            continue

        # Find the first released-high phase, then the first later driven-low
        # phase.  Do not use the last high phase: that adds an ordering demand
        # not stated by the requirement if a design later revisits high.
        high_i = next(
            (i for i, row in enumerate(body) if out(row, 'scl_oen') == 1),
            None,
        )

        if high_i is None:
            if window.closed:
                verdicts.append((False, body[-1].get('edge'), 'SCL was not released high during the WRITE sequence'))
            else:
                verdicts.append((None, body[-1].get('edge'), 'the trace ended before the WRITE SCL high phase was observed'))
            continue

        low_i = next(
            (
                i for i in range(high_i + 1, len(body))
                if out(body[i], 'scl_oen') == 0
            ),
            None,
        )

        if low_i is None:
            if window.closed:
                verdicts.append((False, body[-1].get('edge'), 'SCL was not pulled low after the released-high phase'))
            else:
                verdicts.append((None, body[-1].get('edge'), 'the trace ended before SCL was pulled low again'))
            continue

        idle_i = next(
            (
                i for i in range(low_i, len(body))
                if out(body[i], 'in_idle') == 1
            ),
            None,
        )

        if idle_i is None:
            if window.closed:
                verdicts.append((False, body[-1].get('edge'), 'the FSM did not return to idle after SCL was pulled low'))
            else:
                verdicts.append((None, body[-1].get('edge'), 'the trace ended before the FSM returned to idle'))
            continue

        ack_i = next(
            (
                i for i in range(idle_i, len(body))
                if out(body[i], 'cmd_ack') == 1
            ),
            None,
        )

        if ack_i is None:
            if window.closed:
                verdicts.append((False, body[-1].get('edge'), 'cmd_ack did not pulse after the WRITE sequence'))
            else:
                verdicts.append((None, body[-1].get('edge'), 'the trace ended before cmd_ack pulsed'))
            continue

        ack_row = body[ack_i]
        if ack_row.get('held') != 1:
            verdicts.append((False, ack_row.get('edge'), 'cmd_ack was held for %s edges; the obligation requires a pulse' % ack_row.get('held')))
        else:
            verdicts.append((True, ack_row.get('edge'), 'SCL was released high, pulled low again, the FSM returned idle, and cmd_ack pulsed for one clock'))

    return worst(verdicts)

