def decide(trace):
    from specflow.refmodel.temporal import WHILE_ACTIVE, after, throughout, worst

    def enabled(port):
        return lambda row: row['outputs'].get(port) == 1

    windows = []
    for port in ('scl_oen', 'sda_oen'):
        windows.extend(
            (port, w) for w in after(
                trace,
                enabled(port),
                until=WHILE_ACTIVE,
            )
        )

    verdicts = [
        throughout(
            window,
            lambda row, port=port: row['outputs'].get(port) == 1,
        )
        for port, window in windows
    ]
    return worst(verdicts)

def decide(trace):
    checks = []
    saw = False
    for row in trace:
        outputs = row.get('outputs', {})
        for port in ('scl_oen', 'sda_oen'):
            if outputs.get(port) == 1:
                saw = True
                if outputs.get(port) != 1:
                    checks.append((False, row.get('edge'), f'{port} was not high during its release condition'))
    if checks:
        return checks[0]
    if not saw:
        return (None, None, 'neither declared output enable was high; the release condition did not occur')
    return (True, None, 'scl_oen and/or sda_oen were high during their respective release conditions')

