from specflow.refmodel.temporal import TO_END, after, edges, pulse, worst

def decide(trace):
    sequence_probes = (
        "in_start_sequence",
        "in_stop_sequence",
        "in_read_sequence",
        "in_write_sequence",
    )

    falling = {
        probe: edges(trace, probe, "fall")
        for probe in sequence_probes
    }

    def terminal(row):
        if row["inputs"].get("nReset") == 0 or row["inputs"].get("rst") == 1:
            return False
        if row["outputs"].get("al") == 1:
            return False
        return any(
            row["edge"] in falling[probe]
            for probe in sequence_probes
        )

    windows = after(
        trace,
        terminal,
        until=TO_END,
        aborts=lambda row: (
            row["inputs"].get("nReset") == 0
            or row["inputs"].get("rst") == 1
        ),
    )

    if not windows:
        return (None, None, "no completed START, STOP, READ, or WRITE sequence occurred")

    return worst([
        pulse(w, "cmd_ack", width=1, active=1)
        for w in windows
    ])

def decide(trace):
    sequence_probes = (
        'in_start_sequence',
        'in_stop_sequence',
        'in_read_sequence',
        'in_write_sequence',
    )

    completions = []
    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        prev_out = prev.get('outputs', {})
        out = row.get('outputs', {})
        was_active = any(prev_out.get(p) == 1 for p in sequence_probes)
        is_active = any(out.get(p) == 1 for p in sequence_probes)
        if not was_active or is_active:
            continue
        if row.get('inputs', {}).get('nReset') == 0:
            continue
        if row.get('inputs', {}).get('rst') == 1:
            continue
        if out.get('al') == 1 or prev_out.get('al') == 1:
            continue
        completions.append(i)

    if not completions:
        return (None, None, 'no non-aborted START, STOP, READ, or WRITE sequence completion was observed')

    for i in completions:
        row = trace[i]
        out = row.get('outputs', {})
        if out.get('cmd_ack') != 1:
            return (False, row.get('edge'), 'cmd_ack was not high when the bit-level sequence completed')

        total = 0
        j = i
        while j < len(trace) and trace[j].get('outputs', {}).get('cmd_ack') == 1:
            total += trace[j].get('held', 0)
            j += 1

        if j == len(trace):
            return (None, row.get('edge'), 'cmd_ack was high at completion but the trace ended before its falling edge')
        if total != 1:
            return (False, row.get('edge'), f'cmd_ack was high for {total} clock edges; expected exactly one')

    return (True, trace[completions[-1]].get('edge'), f'{len(completions)} completed bit-level sequence(s) had one-clock cmd_ack pulses')

def decide(trace):
    from specflow.refmodel.temporal import edges

    sequence_probes = (
        "in_start_sequence",
        "in_stop_sequence",
        "in_read_sequence",
        "in_write_sequence",
    )
    falling = {
        probe: edges(trace, probe, "fall")
        for probe in sequence_probes
    }

    terminal_rows = []
    for row in trace:
        inputs = row.get("inputs", {})
        outputs = row.get("outputs", {})
        if inputs.get("nReset") == 0 or inputs.get("rst") == 1:
            continue
        if outputs.get("al") == 1:
            continue
        if inputs.get("ena") != 1:
            continue
        if any(row.get("edge") in falling[probe] for probe in sequence_probes):
            terminal_rows.append(row)

    if not terminal_rows:
        return (None, None, "no non-aborted completed START, STOP, READ, or WRITE terminal state occurred")

    for row in terminal_rows:
        ack = row.get("outputs", {}).get("cmd_ack")
        if ack != 1:
            return (
                False,
                row.get("edge"),
                "cmd_ack was not asserted at the terminal phase; the obligation requires a one-clock-cycle acknowledge pulse"
            )
        if row.get("held") != 1:
            return (
                False,
                row.get("edge"),
                f"cmd_ack was asserted for {row.get('held')} clock edges at the terminal phase; the obligation requires exactly one clock cycle"
            )

    return (
        True,
        terminal_rows[-1].get("edge"),
        f"cmd_ack was asserted for exactly one clock cycle at each of {len(terminal_rows)} completed operation terminal state(s)"
    )

def decide(trace):
    sequence_probes = (
        "in_start_sequence",
        "in_stop_sequence",
        "in_read_sequence",
        "in_write_sequence",
    )

    terminal_indices = []
    for i in range(1, len(trace)):
        row = trace[i]
        prev = trace[i - 1]
        inputs = row.get("inputs", {})
        outputs = row.get("outputs", {})
        prev_outputs = prev.get("outputs", {})

        if inputs.get("nReset") == 0 or inputs.get("rst") == 1:
            continue
        if inputs.get("ena") != 1 or outputs.get("al") == 1:
            continue

        fell = any(
            prev_outputs.get(probe) == 1 and outputs.get(probe) == 0
            for probe in sequence_probes
        )
        if fell:
            terminal_indices.append(i)

    if not terminal_indices:
        return (None, None, "no non-aborted completed START, STOP, READ, or WRITE sequence was observed")

    for start in terminal_indices:
        ack_index = None
        aborted = False
        for j in range(start, len(trace)):
            row = trace[j]
            inputs = row.get("inputs", {})
            outputs = row.get("outputs", {})
            if inputs.get("nReset") == 0 or inputs.get("rst") == 1:
                aborted = True
                break
            if outputs.get("al") == 1:
                aborted = True
                break
            if outputs.get("cmd_ack") == 1:
                ack_index = j
                break

        if aborted:
            continue
        if ack_index is None:
            return (
                False,
                trace[start].get("edge"),
                "the completed bit-level operation did not produce its acknowledge pulse"
            )

        pulse_edges = 0
        k = ack_index
        while k < len(trace):
            row = trace[k]
            if row.get("outputs", {}).get("cmd_ack") != 1:
                break
            pulse_edges += row.get("held", 0)
            k += 1

        if pulse_edges != 1:
            return (
                False,
                trace[ack_index].get("edge"),
                f"cmd_ack was high for {pulse_edges} clock edges; the acknowledge pulse must be high for exactly one clock cycle"
            )

    completed = len(terminal_indices)
    return (
        True,
        trace[terminal_indices[-1]].get("edge"),
        f"cmd_ack provided a one-clock-cycle acknowledge pulse for each of {completed} completed bit-level operation(s)"
    )
